import subprocess, json
def run(rows):
    inp="".join(json.dumps(r, ensure_ascii=False)+"\n" for r in rows)
    p=subprocess.run(["./executable","* | json"], input=inp.encode(), capture_output=True)
    for lineb in p.stdout.splitlines():
        line=lineb.decode()
        parts=line.split('[b=')
        cell=parts[0]
        print(f"line={line!r} cellprefix_chars={len(cell)} bytes={len(cell.encode())} spaces_at_end={len(cell)-len(cell.rstrip(' '))} cell_no_spaces={cell.rstrip(' ')!r} chars={len(cell.rstrip(' '))} bytes={len(cell.rstrip(' ').encode())}")
    print("---")
for v in ["x","héllo","😀😀","e\u0301e\u0301","\t","", "xx"]:
    run([{"a":v,"b":"y"}])
for k in ["","a","é","😀","ab"]:
    run([{k:"","b":"y"}] if k!="b" else [{k:"","z":"y"}])
