#!/usr/bin/env python3
# Independent reimplementation of the `ag` (angle-grinder) command line tool,
# written from the bundled documentation and black-box observation.
import sys, os, re, math, time, struct, json as jsonlib
from fractions import Fraction
from collections import deque, OrderedDict

VERSION = "ag 0.19.6"
I64_MIN = -(1 << 63)
I64_MAX = (1 << 63) - 1
EPSILON = 2.220446049250313e-16
RUST_WS = set([chr(c) for c in (0x09,0x0a,0x0b,0x0c,0x0d,0x20,0x85,0xa0,0x1680,
    0x2000,0x2001,0x2002,0x2003,0x2004,0x2005,0x2006,0x2007,0x2008,0x2009,0x200a,
    0x2028,0x2029,0x202f,0x205f,0x3000)])

def is_rust_ws(ch):
    return ch in RUST_WS

def rust_trim(s):
    return s.strip(''.join(RUST_WS))

def rust_trim_end(s):
    return s.rstrip(''.join(RUST_WS))

def rust_trim_start(s):
    return s.lstrip(''.join(RUST_WS))

def wrap_i64(x):
    x &= (1 << 64) - 1
    if x >= (1 << 63):
        x -= (1 << 64)
    return x

def saturate_i64_from_float(f):
    if math.isnan(f):
        return 0
    if f >= 9223372036854775808.0:
        return I64_MAX
    if f <= -9223372036854775808.0:
        return I64_MIN
    return int(f)  # trunc toward zero

def normalize_float(f):
    if isinstance(f, int) and not isinstance(f, bool):
        return f
    f = float(f)
    if math.isnan(f) or math.isinf(f):
        return f
    if f == math.trunc(f):
        return saturate_i64_from_float(f)
    if 0.0 < f < EPSILON:
        return 0
    return f

# ---------------------------------------------------------------------------
# Date and duration values (stored as epoch/total nanoseconds)

def days_from_civil(y, m, d):
    # Howard Hinnant's algorithm (astronomical year numbering)
    y_adj = y if m > 2 else y - 1
    era = (y_adj if y_adj >= 0 else y_adj - 399) // 400
    yoe = y_adj - era * 400
    doy = (153 * (m - 3 if m > 2 else m + 9) + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468

def civil_from_days(z):
    z += 719468
    era = (z if z >= 0 else z - 146096) // 146097
    doe = z - era * 146097
    yoe = (doe - doe//1460 + doe//36524 - doe//146096) // 365
    y = yoe + era * 400
    doy = doe - (365*yoe + yoe//4 - yoe//100)
    mp = (5*doy + 2)//153
    d = doy - (153*mp+2)//5 + 1
    m = mp + 3 if mp < 10 else mp - 9
    return (y + (1 if m <= 2 else 0), m, d)

def is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

DAYS_IN_MONTH = [31,28,31,30,31,30,31,31,30,31,30,31]
def days_in_month(y, m):
    if m == 2 and is_leap(y):
        return 29
    return DAYS_IN_MONTH[m-1]

class DateValue:
    __slots__ = ('ns',)
    def __init__(self, ns):
        self.ns = int(ns)
    def parts(self):
        days = self.ns // 86_400_000_000_000
        rem = self.ns - days * 86_400_000_000_000
        y, mo, d = civil_from_days(days)
        sec, ns = divmod(rem, 1_000_000_000)
        h, rem2 = divmod(sec, 3600)
        mi, s = divmod(rem2, 60)
        return y, mo, d, h, mi, s, ns
    def __repr__(self):
        return 'DateValue(%r)' % (self.ns,)

class DurationValue:
    __slots__ = ('ns',)
    def __init__(self, ns):
        self.ns = int(ns)
    def __repr__(self):
        return 'DurationValue(%r)' % (self.ns,)

def _format_year(y):
    if 0 <= y <= 9999:
        return '%04d' % y
    if y > 9999:
        return '+%d' % y if False else str(y)
    return '%05d' % y if y < 0 else str(y)  # e.g. -0001 handled poorly below

def _year_str(y):
    if 0 <= y <= 9999:
        return '%04d' % y
    if y < 0:
        return '-%04d' % (-y)
    return str(y)

def _frac_str(ns):
    if ns == 0:
        return ''
    if ns % 1_000_000 == 0:
        return '.%03d' % (ns // 1_000_000)
    if ns % 1_000 == 0:
        return '.%06d' % (ns // 1_000)
    return '.%09d' % ns

def date_render(v):  # legacy display: "2020-01-02 03:04:05 UTC"
    y, mo, d, h, mi, s, ns = v.parts()
    return '%s-%02d-%02d %02d:%02d:%02d%s UTC' % (_year_str(y), mo, d, h, mi, s, _frac_str(ns))

def date_rfc3339(v, zulu=False):
    y, mo, d, h, mi, s, ns = v.parts()
    suffix = 'Z' if zulu else '+00:00'
    return '%s-%02d-%02dT%02d:%02d:%02d%s%s' % (_year_str(y), mo, d, h, mi, s, _frac_str(ns), suffix)

def duration_render(v):
    total = v.ns
    if total == 0:
        return ''
    def tdiv(a, b):
        q = abs(a) // abs(b)
        return q if (a < 0) == (b < 0) else -q
    units = [('w', 7*86400*10**9), ('d', 86400*10**9), ('h', 3600*10**9),
             ('m', 60*10**9), ('s', 10**9), ('ms', 10**6), ('us', 10**3)]
    out = []
    rem = total
    for name, size in units:
        q = tdiv(rem, size)
        if q != 0:
            out.append('%d%s' % (q, name))
            rem -= q * size
    return ''.join(out)

def duration_iso(v):
    total = v.ns
    if total == 0:
        return 'P0D'
    sign = '-' if total < 0 else ''
    a = abs(total)
    secs, ns = divmod(a, 10**9)
    if ns:
        frac = ('%09d' % ns).rstrip('0')
        return '%sPT%d.%sS' % (sign, secs, frac)
    return '%sPT%dS' % (sign, secs)

def timedelta_debug(v):
    secs = v.ns // 10**9
    nanos = v.ns - secs * 10**9
    return 'TimeDelta { secs: %d, nanos: %d }' % (secs, nanos)

# ---------------------------------------------------------------------------
# Value helpers

def is_number(v):
    return (isinstance(v, int) and not isinstance(v, bool)) or isinstance(v, float)

def copy_value(v):
    if isinstance(v, list):
        return [copy_value(x) for x in v]
    if isinstance(v, dict):
        return {k: copy_value(x) for k, x in v.items()}
    return v

_SHORT_DIGITS_CACHE = {}
def shortest_digits(f):
    """Return (neg, digits_without_point, exp10) so value = d.ddd * 10**exp10
    using Python's shortest repr digit sequence."""
    if f == 0:
        return (math.copysign(1.0, f) < 0, '0', 0)
    r = repr(abs(f))
    mant, _, exp = r.partition('e')
    e = int(exp) if exp else 0
    if '.' in mant:
        ip, fp = mant.split('.')
    else:
        ip, fp = mant, ''
    digits = (ip + fp).lstrip('0')
    # exponent of first significant digit
    if ip.strip('0'):
        e10 = len(ip) - 1 + e
    else:
        # count leading zeros in fraction
        k = 0
        while k < len(fp) and fp[k] == '0':
            k += 1
        e10 = -(k + 1) + e
    digits = digits.rstrip('0') or '0'
    return (f < 0, digits, e10)

def format_float_json(f):
    """serde_json/ryu style formatting for a finite raw float."""
    if math.isnan(f) or math.isinf(f):
        return 'null'
    if f == 0:
        return '-0.0' if math.copysign(1.0, f) < 0 else '0.0'
    neg, digits, e10 = shortest_digits(f)
    sign = '-' if neg else ''
    if e10 >= 16 or e10 <= -6:
        if len(digits) == 1:
            return '%s%se%d' % (sign, digits, e10)
        return '%s%s.%se%d' % (sign, digits[0], digits[1:], e10)
    return sign + _digits_to_decimal(digits, e10, trailing_point=True)

def _digits_to_decimal(digits, e10, trailing_point=False):
    if e10 >= 0:
        if len(digits) > e10 + 1:
            return digits[:e10+1] + '.' + digits[e10+1:]
        s = digits + '0' * (e10 + 1 - len(digits))
        return s + ('.0' if trailing_point else '')
    else:
        return '0.' + '0' * (-e10 - 1) + digits

def rust_float_display(f):
    """Rust {} formatting for f64."""
    if math.isnan(f):
        return 'NaN'
    if math.isinf(f):
        return '-inf' if f < 0 else 'inf'
    if f == 0:
        return '-0' if math.copysign(1.0, f) < 0 else '0'
    neg, digits, e10 = shortest_digits(f)
    return ('-' if neg else '') + _digits_to_decimal(digits, e10, trailing_point=False)

def rust_float_debug(f):
    """Rust {:?} formatting for f64 (approx: like JSON but keeps .0)."""
    if math.isnan(f):
        return 'NaN'
    if math.isinf(f):
        return '-inf' if f < 0 else 'inf'
    if f == 0:
        return '-0.0' if math.copysign(1.0, f) < 0 else '0.0'
    neg, digits, e10 = shortest_digits(f)
    sign = '-' if neg else ''
    # Rust Debug uses exponent for large/small like ryu with .0 retained
    if e10 >= 16 or e10 <= -6:
        if len(digits) == 1:
            return '%s%s.0e%d' % (sign, digits, e10) if False else '%s%se%d' % (sign, digits, e10)
        return '%s%s.%se%d' % (sign, digits[0], digits[1:], e10)
    return sign + _digits_to_decimal(digits, e10, trailing_point=True)

def float_fixed2(f):
    if math.isnan(f):
        return 'NaN'
    if math.isinf(f):
        return '-inf' if f < 0 else 'inf'
    return format(f, '.2f')

def rust_debug_str(s):
    out = '"'
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out += '\\"'
        elif ch == '\\':
            out += '\\\\'
        elif ch == '\n':
            out += '\\n'
        elif ch == '\r':
            out += '\\r'
        elif ch == '\t':
            out += '\\t'
        elif o == 0:
            out += '\\0'
        elif o < 0x20 or o == 0x7f:
            out += '\\u{%x}' % o
        else:
            out += ch
    return out + '"'

def render_value(v):
    if v is None:
        return 'None'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return float_fixed2(v)
    if isinstance(v, str):
        return v
    if isinstance(v, list):
        return '[' + ', '.join(render_value(x) for x in v) + ']'
    if isinstance(v, dict):
        return '{' + ', '.join('%s:%s' % (k, render_value(v[k])) for k in sorted(v.keys())) + '}'
    if isinstance(v, DateValue):
        return date_render(v)
    if isinstance(v, DurationValue):
        return duration_render(v)
    return str(v)

def debug_value(v):
    """Value::to_string()-style text used by concat/errors."""
    if v is None:
        return 'None'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return rust_float_display(v)
    if isinstance(v, str):
        return v
    if isinstance(v, list):
        return '[' + ', '.join(enum_debug(x) for x in v) + ']'
    if isinstance(v, dict):
        return '{' + ', '.join('%s: %s' % (rust_debug_str(k), enum_debug(v[k])) for k in sorted(v.keys())) + '}'
    if isinstance(v, DateValue):
        return date_rfc3339(v, zulu=True)
    if isinstance(v, DurationValue):
        return timedelta_debug(v)
    return str(v)

def enum_debug(v):
    if v is None:
        return 'None'
    if isinstance(v, bool):
        return 'Bool(%s)' % ('true' if v else 'false')
    if isinstance(v, int):
        return 'Int(%d)' % v
    if isinstance(v, float):
        return 'Float(%s)' % rust_float_debug(v)
    if isinstance(v, str):
        return 'Str(%s)' % rust_debug_str(v)
    if isinstance(v, list):
        return 'Array([' + ', '.join(enum_debug(x) for x in v) + '])'
    if isinstance(v, dict):
        inner = '{' + ', '.join('%s: %s' % (rust_debug_str(k), enum_debug(v[k])) for k in sorted(v.keys())) + '}'
        return 'Obj(%s)' % inner
    if isinstance(v, DateValue):
        return 'Date(%s)' % date_rfc3339(v, zulu=True)
    if isinstance(v, DurationValue):
        return 'Duration(%s)' % timedelta_debug(v)
    return str(v)

def json_escape_str(s):
    out = []
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\b':
            out.append('\\b')
        elif ch == '\f':
            out.append('\\f')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif o < 0x20:
            out.append('\\u%04x' % o)
        else:
            out.append(ch)
    return '"' + ''.join(out) + '"'

def json_value_str(v):
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return format_float_json(v)
    if isinstance(v, str):
        return json_escape_str(v)
    if isinstance(v, list):
        return '[' + ','.join(json_value_str(x) for x in v) + ']'
    if isinstance(v, dict):
        return '{' + ','.join('%s:%s' % (json_escape_str(k), json_value_str(v[k])) for k in sorted(v.keys())) + '}'
    if isinstance(v, DateValue):
        return json_escape_str(date_rfc3339(v))
    if isinstance(v, DurationValue):
        return json_escape_str(duration_iso(v))
    return 'null'

_RUST_F64_RE = re.compile(r'^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$')
def rust_parse_f64(s):
    t = s
    low = t.lower()
    neg = False
    body = low
    if body.startswith(('+', '-')):
        neg = body[0] == '-'
        body = body[1:]
    if body in ('inf', 'infinity'):
        return -math.inf if neg else math.inf
    if body == 'nan':
        return math.nan
    if not _RUST_F64_RE.match(t):
        return None
    try:
        return float(t)
    except Exception:
        return None

_RUST_I64_RE = re.compile(r'^[+-]?[0-9]+$')
def rust_parse_i64(s):
    if not _RUST_I64_RE.match(s):
        return None
    try:
        v = int(s, 10)
    except Exception:
        return None
    if v < I64_MIN or v > I64_MAX:
        return None
    return v

def infer_value(s):
    """Value::from(String): trim, then int / float / bool, else string."""
    t = rust_trim(s)
    if t == '':
        return ''
    iv = rust_parse_i64(t)
    if iv is not None:
        return iv
    fv = rust_parse_f64(t)
    if fv is not None:
        return normalize_float(fv)
    if t == 'true':
        return True
    if t == 'false':
        return False
    return t

class EvalError(Exception):
    pass

def _filtered_number(s):
    return ''.join(ch for ch in s if ch.isnumeric() or ch == '.')

def _str_to_number(s):
    f = _filtered_number(s)
    if f == '':
        return None
    iv = rust_parse_i64(f)
    if iv is not None:
        return iv
    fv = rust_parse_f64(f)
    if fv is None:
        return None
    return normalize_float(fv)

def as_number(v):
    """num() / arithmetic conversion. Returns Int/Float or raises EvalError."""
    if isinstance(v, bool):
        raise EvalError('Expected number, found %s' % debug_value(v))
    if isinstance(v, int):
        return v
    if isinstance(v, float):
        return v
    if isinstance(v, str):
        n = _str_to_number(v)
        if n is None:
            raise EvalError('Expected number, found %s' % debug_value(v))
        return n
    if isinstance(v, DateValue):
        return v.ns // 1_000_000
    raise EvalError('Expected number, found %s' % debug_value(v))

def agg_number(v):
    """Numeric conversion for aggregators/total: Int/Float/Str only, else None."""
    if isinstance(v, bool):
        return None
    if isinstance(v, int) or isinstance(v, float):
        return v
    if isinstance(v, str):
        return _str_to_number(v)
    return None

def to_f64(num):
    if isinstance(num, float):
        return num
    try:
        return float(num)
    except OverflowError:
        return math.inf if num > 0 else -math.inf
