# ---------------------------------------------------------------------------
# JSON parsing (serde/simd-json-like number handling)

class RawJsonNumber:
    __slots__ = ('text',)
    def __init__(self, text):
        self.text = text

def _json_number_value(text):
    if re.fullmatch(r'-?[0-9]+', text):
