    # then scaled by a power of ten) to mirror the reference's 1-ulp quirks.
    neg = text.startswith('-')
    body = text[1:] if text[:1] in '+-' else text
    mant_str, _, exp_str = body.lower().partition('e')
    exp = int(exp_str) if exp_str else 0
    if '.' in mant_str:
        ip, fp = mant_str.split('.')
    else:
        ip, fp = mant_str, ''
    digits = ip + fp
    mant = 0.0
    for dch in digits:
        mant = mant * 10.0 + (ord(dch) - 48)
    e10 = exp - len(fp)
    if mant == 0.0:
        return 0
    try:
        if e10 >= 0:
            f = mant * (10.0 ** e10)
        else:
            f = mant / (10.0 ** (-e10))
    except OverflowError:
        f = math.inf
    if neg:
        f = -f
    if math.isinf(f):
        raise ValueError('json number out of range')
    return normalize_float(f)

