    if isinstance(v, RawJsonNumber):
        return _json_number_value(v.text)
    if isinstance(v, dict):
        out = {}
        for k, x in v.items():
            if _has_surrogate(k):
                raise ValueError('surrogate in json string')
            out[k] = _convert_json(x)
        return out
    if isinstance(v, list):
        return [_convert_json(x) for x in v]
    if isinstance(v, str):
        if _has_surrogate(v):
            raise ValueError('surrogate in json string')
        return v
    return v

def _has_surrogate(s):
    return any(0xD800 <= ord(c) <= 0xDFFF for c in s)

def _json_depth_ok(s):
    depth = 0
    in_str = False
    esc = False
    for ch in s:
        if in_str:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch in '[{':
            depth += 1
            if depth > 127:
                return False
        elif ch in ']}':
            depth -= 1
    return True

def parse_json_text(s):
    """Return converted value or raise ValueError."""
    if not _json_depth_ok(s):
        raise ValueError('recursion limit')
    def bad_const(x):
