        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, int) and isinstance(b, int):
        return a == b
    if isinstance(a, float) and isinstance(b, float):
        return a == b
    if isinstance(a, float) or isinstance(b, float) or isinstance(a, int) or isinstance(b, int):
        return False
    if a is None or b is None:
        return a is None and b is None
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(value_eq(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return set(a.keys()) == set(b.keys()) and all(value_eq(a[k], b[k]) for k in a)
    if isinstance(a, DateValue) and isinstance(b, DateValue):
        return a.ns == b.ns
    if isinstance(a, DurationValue) and isinstance(b, DurationValue):
        return a.ns == b.ns
    return False

def type_rank(v):
    if v is None: return 0
    if isinstance(v, bool): return 1
    if isinstance(v, int): return 2
    if isinstance(v, float): return 3
    if isinstance(v, str): return 4
    if isinstance(v, DateValue): return 5
    if isinstance(v, DurationValue): return 6
    if isinstance(v, list): return 7
    if isinstance(v, dict): return 8
    return 9

def partial_cmp(a, b):
    """-1/0/1 or None (incomparable), mirroring Value::partial_cmp."""
    if is_number(a) and is_number(b):
        if isinstance(a, int) and isinstance(b, int):
            return (a > b) - (a < b)
        fa, fb = to_f64(a), to_f64(b)
        if math.isnan(fa) or math.isnan(fb):
            return None
        return (fa > fb) - (fa < fb)
    ra, rb = type_rank(a), type_rank(b)
    if ra != rb:
        return (ra > rb) - (ra < rb)
    if a is None:
        return 0
    if isinstance(a, bool):
        return (a > b) - (a < b)
    if isinstance(a, str):
        return (a > b) - (a < b)
    if isinstance(a, DateValue):
        return (a.ns > b.ns) - (a.ns < b.ns)
    if isinstance(a, DurationValue):
        return (a.ns > b.ns) - (a.ns < b.ns)
    if isinstance(a, (list, dict)):
        return 0 if value_eq(a, b) else None
    return 0

def sort_cmp_value(a, b):
    """Total-ish comparison for sorting (NaN greatest among numbers)."""
    if is_number(a) and is_number(b):
        fa, fb = to_f64(a), to_f64(b)
        a_nan, b_nan = math.isnan(fa), math.isnan(fb)
        if a_nan or b_nan:
            return 0 if (a_nan and b_nan) else (1 if a_nan else -1)
        if isinstance(a, int) and isinstance(b, int):
            return (a > b) - (a < b)
        return (fa > fb) - (fa < fb)
    c = partial_cmp(a, b)
    return 0 if c is None else c

def encode_hashable(v):
    if v is None: return (0,)
    if isinstance(v, bool): return (1, v)
    if isinstance(v, int): return (2, v)
    if isinstance(v, float):
        if math.isnan(v): return (3, 'nan')
        return (3, v + 0.0)
    if isinstance(v, str): return (4, v)
    if isinstance(v, DateValue): return (5, v.ns)
    if isinstance(v, DurationValue): return (6, v.ns)
    if isinstance(v, list): return (7, tuple(encode_hashable(x) for x in v))
    if isinstance(v, dict): return (8, tuple(sorted((k, encode_hashable(x)) for k, x in v.items())))
    return (9, str(v))

