 'oct':10,'october':10,'nov':11,'november':11,'dec':12,'december':12}
WEEKDAYS = {'mon','monday','tue','tues','tuesday','wed','wednesday','thu','thur','thurs','thursday','fri','friday','sat','saturday','sun','sunday'}
