def _now_parts():
    ns = time.time_ns()
    dv = DateValue(ns)
    return dv.parts()

def _make_date(y, mo, d, h, mi, s, ns):
    if mo is not None and not (1 <= mo <= 12):
        raise DateParseError('ImpossibleTimestamp("Invalid month")')
    if h is not None and not (0 <= h <= 23):
        # original allows e.g. 24? probe said 25 invalid; treat >23 invalid except 24:00? keep >24
        if h > 24 or h == 24 and (mi or s or ns):
            raise DateParseError('ImpossibleTimestamp("Invalid hour")')
    if mi is not None and not (0 <= mi <= 59):
        raise DateParseError('ImpossibleTimestamp("Invalid minute")')
    if s is not None and not (0 <= s <= 60):
        raise DateParseError('ImpossibleTimestamp("Invalid second")')
    now = _now_parts()
    if y is None: y = now[0]
    if mo is None: mo = now[1]
    if d is None: d = now[2]
    if h is None: h = 0
    if mi is None: mi = 0
    if s is None: s = 0
    if ns is None: ns = 0
    if not (1 <= mo <= 12):
        raise DateParseError('ImpossibleTimestamp("Invalid month")')
    dim = days_in_month(y, mo)
    if d < 1:
        d = 1
    if d > dim:
        d = dim
    days = days_from_civil(y, mo, d)
    total_ns = (((days * 24 + h) * 60 + mi) * 60 + s) * 1_000_000_000 + ns
    return DateValue(total_ns)

