class RawJsonNumber:
    __slots__ = ('text',)
    def __init__(self, text):
        self.text = text

def _json_number_value(text):
    if re.fullmatch(r'-?[0-9]+', text):
        try:
            v = int(text, 10)
        except Exception:
            v = I64_MAX if not text.startswith('-') else I64_MIN
            return v
        if v > I64_MAX:
            return I64_MAX
        if v < I64_MIN:
            return I64_MIN
        return v
    # float token: approximate parser (mantissa accumulated as f64 digits,
    # then scaled by a power of ten) to mirror the reference's 1-ulp quirks.
    neg = text.startswith('-')
    body = text[1:] if text[:1] in '+-' else text
    mant_str, _, exp_str = body.lower().partition('e')
    exp = int(exp_str) if exp_str else 0
    if '.' in mant_str:
        ip, fp = mant_str.split('.')
    else:
        ip, fp = mant_str, ''
    digits = ip + fp
    mant = 0.0
    for dch in digits:
        mant = mant * 10.0 + (ord(dch) - 48)
    e10 = exp - len(fp)
    if mant == 0.0:
        return 0
    try:
        if e10 >= 0:
            f = mant * (10.0 ** e10)
        else:
            f = mant / (10.0 ** (-e10))
    except OverflowError:
        f = math.inf
    if neg:
        f = -f
    if math.isinf(f):
        raise ValueError('json number out of range')
    return normalize_float(f)

def _convert_json(v):
    if isinstance(v, RawJsonNumber):
        return _json_number_value(v.text)
    if isinstance(v, dict):
        out = {}
        for k, x in v.items():
            if _has_surrogate(k):
                raise ValueError('surrogate in json string')
            out[k] = _convert_json(x)
        return out
    if isinstance(v, list):
        return [_convert_json(x) for x in v]
    if isinstance(v, str):
        if _has_surrogate(v):
            raise ValueError('surrogate in json string')
        return v
    return v

def _has_surrogate(s):
    return any(0xD800 <= ord(c) <= 0xDFFF for c in s)

def _json_depth_ok(s):
    depth = 0
    in_str = False
    esc = False
    for ch in s:
        if in_str:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch in '[{':
            depth += 1
            if depth > 127:
                return False
        elif ch in ']}':
            depth -= 1
    return True

def parse_json_text(s):
    """Return converted value or raise ValueError."""
    if not _json_depth_ok(s):
        raise ValueError('recursion limit')
    def bad_const(x):
        raise ValueError('invalid constant %s' % x)
    v = jsonlib.loads(s, parse_int=lambda t: RawJsonNumber(t),
                      parse_float=lambda t: RawJsonNumber(t),
                      parse_constant=bad_const)
    return _convert_json(v)
