            out.append(ch)
            self.pos += 1
        raise ParseFailure('__unterminated_string__:%d:%d:%s' % (start, self.pos, ctx))

IDENT_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
INT_TOKEN_RE = re.compile(r'-?[0-9]+')

def parse_escaped_segment(sc):
    """At '['; parse ["..."] with no spaces. Return name or None."""
    save = sc.pos
    if sc.pos + 1 >= sc.n or sc.s[sc.pos+1] not in '"\'':
        return None
    sc.pos += 1
    try:
        name, _, _ = sc.parse_string()
    except ParseFailure:
        sc.pos = save
        return None
    if sc.peek() != ']':
        sc.pos = save
        return None
    sc.pos += 1
    return name

def parse_column_path(sc):
    """Parse a column reference starting at pos. Return Expr or None."""
    start = sc.pos
    parts = []
    if sc.peek() == '[':
        name = parse_escaped_segment(sc)
        if name is None:
            return None
        parts.append(('key', name))
    else:
        m = IDENT_RE.match(sc.s, sc.pos)
        if not m:
            return None
        parts.append(('key', m.group(0)))
        sc.pos = m.end()
    while True:
        if sc.peek() == '.':
            save = sc.pos
            sc.pos += 1
            if sc.peek() == '[':
                nm = parse_escaped_segment(sc)
                if nm is None:
                    sc.pos = save; break
                parts.append(('key', nm)); continue
            m = IDENT_RE.match(sc.s, sc.pos)
            if not m:
                sc.pos = save; break
            parts.append(('key', m.group(0)))
            sc.pos = m.end(); continue
        if sc.peek() == '[':
            save = sc.pos
            m = re.match(r'\[(-?[0-9]+)\]', sc.s[sc.pos:])
            if not m:
                break
            idx = rust_parse_i64(m.group(1))
            if idx is None:
                break
            parts.append(('index', idx, m.group(1)))
            sc.pos += m.end(); continue
        break
    return Expr('col', (parts,), (start, sc.pos))

DURATION_UNITS = [('ns', 1), ('us', 1000), ('ms', 1000**2), ('s', 1000**3),
                  ('m', 60*1000**3), ('h', 3600*1000**3), ('d', 86400*1000**3), ('w', 7*86400*1000**3)]
DURATION_SEG_RE = re.compile(r'([0-9]+)(ns|us|ms|s|m|h|d|w)')

def try_parse_duration_literal(sc, allow_negative=False):
    start = sc.pos
    pos = sc.pos
    neg = False
    if allow_negative and sc.s[pos:pos+1] == '-':
        neg = True; pos += 1
    total = 0
    count = 0
    p = pos
    while True:
        m = DURATION_SEG_RE.match(sc.s, p)
        if not m:
            break
        amount = rust_parse_i64(m.group(1))
        if amount is None:
            return None
        unit_ns = dict(DURATION_UNITS)[m.group(2)]
        total += amount * unit_ns
        count += 1
        p = m.end()
    if count == 0:
        return None
    if neg:
        total = -total
    sc.pos = p
    return Expr('lit', (DurationValue(total),), (start, p))

def expr_parse_error(sc, title, start, end=None):
    if end is None:
        end = sc.pos
    parse_fail(sc.s, title, start, max(end - start, 0))

class ExprParser:
    def __init__(self, sc):
        self.sc = sc

    def parse(self):
        return self.parse_or()

    def _word_op(self, word):
        sc = self.sc
        save = sc.pos
        skipped = sc.skip_ws()
        if skipped and sc.starts(word):
            after = sc.pos + len(word)
            # reference matches the literal word, then needs ws before operand
            sc.pos = after
            if sc.skip_ws() == 0:
                parse_fail(sc.s, "expecting an operand for '%s' operator" % word, save, max(sc.pos - save, 1))
            return True
        sc.pos = save
        return False

    def parse_or(self):
        left = self.parse_and()
        while True:
            sc = self.sc
            save = sc.pos
            sc.skip_ws()
            if sc.starts('||'):
                sc.pos += 2
                right = self.parse_and()
                left = Expr('or', (left, right), (left.span[0], right.span[1]))
                continue
            sc.pos = save
            if self._word_op('or'):
                right = self.parse_and()
                left = Expr('or', (left, right), (left.span[0], right.span[1]))
                continue
            break
        return left

    def parse_and(self):
        left = self.parse_cmp()
        while True:
            sc = self.sc
            save = sc.pos
            sc.skip_ws()
            if sc.starts('&&'):
                sc.pos += 2
                right = self.parse_cmp()
                left = Expr('and', (left, right), (left.span[0], right.span[1]))
                continue
            sc.pos = save
            if self._word_op('and'):
                right = self.parse_cmp()
                left = Expr('and', (left, right), (left.span[0], right.span[1]))
                continue
            break
        return left

    def parse_cmp(self):
        left = self.parse_add()
        sc = self.sc
        save = sc.pos
        sc.skip_ws()
        op = None
        for cand in ('==', '!=', '<>', '<=', '>=', '<', '>'):
            if sc.starts(cand):
                op = cand; break
        if op is None:
            sc.pos = save
            return left
        sc.pos += len(op)
        # RHS primary must be valid; custom message if it starts badly
        rhs_save = sc.pos
        sc.skip_ws()
        if sc.eof() or sc.peek() in '|,)-.':
            parse_fail(sc.s, 'expecting the right-hand-side of the comparison', rhs_save, max(sc.pos - rhs_save, 0))
        right = self.parse_add()
        return Expr('cmp', (op, left, right), (left.span[0], right.span[1]))

    def parse_add(self):
        left = self.parse_mul()
        while True:
            sc = self.sc
            save = sc.pos
            sc.skip_ws()
            ch = sc.peek()
            if ch == '+' or ch == '-':
                sc.pos += 1
                self._require_operand(save)
                right = self.parse_mul()
                left = Expr('bin', (ch, left, right), (left.span[0], right.span[1]))
                continue
            sc.pos = save
            return left

    def parse_mul(self):
        left = self.parse_unary()
        while True:
            sc = self.sc
            save = sc.pos
            sc.skip_ws()
            ch = sc.peek()
            if ch == '*' or ch == '/':
                sc.pos += 1
                self._require_operand(save)
                right = self.parse_unary()
                left = Expr('bin', (ch, left, right), (left.span[0], right.span[1]))
                continue
            sc.pos = save
            return left

    def _require_operand(self, op_pos):
        sc = self.sc
        sc.skip_ws()
        if sc.eof() or sc.peek() in '|,)*/-+':
            parse_fail(sc.s, 'expecting an operand for binary operator', op_pos, max(sc.pos - op_pos, 1))

    def parse_unary(self):
        sc = self.sc
        sc.skip_ws()
        start = sc.pos
        if sc.peek() == '!' and not sc.starts('!='):
            sc.pos += 1
            sc.skip_ws()
            if sc.peek() == '!':
                parse_fail(sc.s, 'expecting expression for unary operator', start, sc.pos - start + 1)
            operand = self.parse_primary()
            return Expr('not', (operand,), (start, operand.span[1]))
        return self.parse_primary()

    def parse_primary(self):
        sc = self.sc
        sc.skip_ws()
        start = sc.pos
        ch = sc.peek()
        if ch == '(':
            sc.pos += 1
            inner = self.parse()
            sc.skip_ws()
            if sc.peek() != ')':
                parse_fail(sc.s, 'expecting an expression', start, max(sc.pos - start, 1))
            sc.pos += 1
            inner2 = Expr(inner.kind, inner.args, (start, sc.pos))
            inner2 = _wrap_paren(inner, start, sc.pos)
            return inner2
        if ch in '"\'':
            val, st, en = sc.parse_string()
            return Expr('lit', (val,), (st, en))
        if ch.isdigit():
            dur = try_parse_duration_literal(sc)
            if dur is not None:
                return dur
            m = re.match(r'[0-9]+', sc.s[sc.pos:])
            txt = m.group(0)
            sc.pos += m.end()
            try:
                v = int(txt, 10)
            except Exception:
                v = I64_MAX
            if v > I64_MAX:
                v = I64_MAX
            # digits directly followed by letters/dots are invalid; surface that
            return Expr('lit', (v,), (start, sc.pos))
        if ch == '[':
            col = parse_column_path(sc)
            if col is None:
                parse_fail(sc.s, 'expecting an expression', start, 1)
            return col
        m = IDENT_RE.match(sc.s, sc.pos)
        if m:
            name = m.group(0)
            after = m.end()
            # function call: name immediately followed by '('
            if after < sc.n and sc.s[after] == '(':
                return self.parse_call(name, start, after)
            if name in ('true', 'false', 'null'):
                # only a literal if not a path continuation
                nxt = sc.s[after] if after < sc.n else ''
                if nxt not in '.[':
                    sc.pos = after
                    val = True if name == 'true' else (False if name == 'false' else None)
                    return Expr('lit', (val,), (start, after))
            col = parse_column_path(sc)
            if col is not None:
                return col
        # invalid primary
        parse_fail(sc.s, 'expecting an expression', start, 1)

    def parse_call(self, name, start, after):
        sc = self.sc
        sc.pos = after + 1  # past '('
        args = []
        sc.skip_ws()
        if sc.peek() != ')':
            while True:
                arg = self.parse()
                args.append(arg)
                sc.skip_ws()
                if sc.peek() == ',':
                    sc.pos += 1
                    sc.skip_ws()
                    continue
                break
        sc.skip_ws()
        if sc.peek() != ')':
            parse_fail(sc.s, 'unhandled input', sc.pos, 1)
        sc.pos += 1
        if name == 'if':
            if len(args) != 3:
                parse_fail(sc.s, "the 'if' operator expects exactly 3 arguments, the condition, value-if-true, and value-if-false",
                           start, sc.pos - start)
            return Expr('if', tuple(args), (start, sc.pos))
        if name not in KNOWN_FUNCTIONS:
            raise StartupError('Error: Unknown function %s' % name)
        return Expr('call', (name, tuple(args)), (start, sc.pos))

def _wrap_paren(inner, start, end):
    return Expr('paren', (inner,), (start, end))

def unwrap(e):
    while e.kind == 'paren':
        e = e.args[0]
    return e

def eval_expr(e, record):
    k = e.kind
    if k == 'paren':
        return eval_expr(e.args[0], record)
    if k == 'lit':
        return copy_value(e.args[0])
    if k == 'col':
        return eval_column(e.args[0], record)
    if k == 'not':
        v = eval_expr(e.args[0], record)
        if not isinstance(v, bool):
            raise EvalError('Expected boolean, found %s' % debug_value(v))
        return not v
    if k == 'and':
        left = eval_expr(e.args[0], record)
        if not isinstance(left, bool):
            raise EvalError('Expected boolean, found %s' % debug_value(left))
        if not left:
            return False
        right = eval_expr(e.args[1], record)
        if not isinstance(right, bool):
            raise EvalError('Expected boolean, found %s' % debug_value(right))
        return right
    if k == 'or':
        left = eval_expr(e.args[0], record)
        if not isinstance(left, bool):
            raise EvalError('Expected boolean, found %s' % debug_value(left))
        if left:
            return True
        right = eval_expr(e.args[1], record)
        if not isinstance(right, bool):
            raise EvalError('Expected boolean, found %s' % debug_value(right))
        return right
    if k == 'cmp':
        op, le, re_ = e.args
        lv = eval_expr(le, record); rv = eval_expr(re_, record)
        if op == '==':
            return value_eq(lv, rv)
        if op in ('!=', '<>'):
            return not value_eq(lv, rv)
        c = partial_cmp(lv, rv)
        if c is None:
            return False
        if op == '<': return c < 0
        if op == '<=': return c <= 0
        if op == '>': return c > 0
        if op == '>=': return c >= 0
    if k == 'bin':
        op, le, re_ = e.args
        lv = eval_expr(le, record); rv = eval_expr(re_, record)
        return eval_arith(op, lv, rv)
    if k == 'if':
        cond = eval_expr(e.args[0], record)
        if not isinstance(cond, bool):
            raise EvalError('Expected boolean, found %s' % debug_value(cond))
        return eval_expr(e.args[1] if cond else e.args[2], record)
    if k == 'call':
        name, arg_exprs = e.args
        vals = [eval_expr(a, record) for a in arg_exprs]
        return call_function(name, vals)
    raise EvalError('bad expression')

def eval_column(parts, record):
    first = parts[0][1]
    if first not in record.data:
        raise EvalError('No value for key %s' % rust_debug_str(first))
    cur = record.data[first]
    for part in parts[1:]:
        if part[0] == 'key':
            key = part[1]
            if not isinstance(cur, dict):
                raise EvalError('Expected object, found %s' % render_value(cur))
            if key not in cur:
                raise EvalError('No value for key %s' % rust_debug_str(key))
            cur = cur[key]
        else:
            idx = part[1]
            if not isinstance(cur, list):
                raise EvalError('Expected array, found %s' % render_value(cur))
            j = idx if idx >= 0 else len(cur) + idx
            if j < 0 or j >= len(cur):
                raise EvalError('Index %d out of range' % idx)
            cur = cur[j]
    return copy_value(cur)

def eval_arith(op, lv, rv):
    # date / duration special cases
    if isinstance(lv, DateValue) and isinstance(rv, DateValue) and op == '-':
        return DurationValue(lv.ns - rv.ns)
    if isinstance(lv, DateValue) and isinstance(rv, DurationValue):
        if op == '+': return DateValue(lv.ns + rv.ns)
        if op == '-': return DateValue(lv.ns - rv.ns)
    if isinstance(lv, DurationValue) and isinstance(rv, DateValue) and op == '+':
        return DateValue(rv.ns + lv.ns)
    if isinstance(lv, DurationValue) and isinstance(rv, DurationValue):
        if op == '+': return DurationValue(lv.ns + rv.ns)
        if op == '-': return DurationValue(lv.ns - rv.ns)
    if isinstance(lv, DurationValue) and isinstance(rv, int) and not isinstance(rv, bool):
        if op == '*': return DurationValue(lv.ns * rv)
        if op == '/':
            if rv == 0:
                raise EvalError('Expected numeric operands, found %s / 0' % debug_value(lv))
            q = abs(lv.ns) // abs(rv)
            if (lv.ns < 0) != (rv < 0): q = -q
            return DurationValue(q)
    if isinstance(rv, DurationValue) and isinstance(lv, int) and not isinstance(lv, bool) and op == '*':
        return DurationValue(rv.ns * lv)
    # numeric
    try:
        ln = as_number(lv); rn = as_number(rv)
    except EvalError:
        raise EvalError('Expected numeric operands, found %s %s %s' % (debug_value(lv), op, debug_value(rv)))
    if op == '/':
        fa, fb = to_f64(ln), to_f64(rn)
        if fb == 0.0:
            if fa == 0.0 or math.isnan(fa):
                res = math.nan
            else:
                res = math.copysign(math.inf, fa) * math.copysign(1.0, fb)
                # sign of infinite result: sign(fa) * sign(fb)
                res = math.inf if (fa > 0) == (math.copysign(1.0, fb) > 0) else -math.inf
                if math.isinf(fa) and fa < 0:
                    res = -res if False else res
            return normalize_float(res)
        return normalize_float(fa / fb)
    both_float_orig = isinstance(lv, float) and isinstance(rv, float)
    if isinstance(ln, int) and isinstance(rn, int):
        if op == '+': return wrap_i64(ln + rn)
        if op == '-': return wrap_i64(ln - rn)
        if op == '*': return wrap_i64(ln * rn)
    fa, fb = to_f64(ln), to_f64(rn)
    if op == '+': res = fa + fb
    elif op == '-': res = fa - fb
    else: res = fa * fb
    if both_float_orig:
        return float(res)
    return normalize_float(res)
