# ---------------------------------------------------------------------------
# Errors / ariadne-style reports

class ParseFailure(Exception):
    """Rich parse failure: message is full stderr text to print."""
    def __init__(self, text):
        super().__init__(text)
        self.text = text

class StartupError(Exception):
    def __init__(self, text):
        super().__init__(text)
        self.text = text

def rich_report(query, title, start, length, label=None, helps=()):
    # locate line
    start = max(0, min(start, len(query)))
    line_start = query.rfind('\n', 0, start) + 1
    line_end = query.find('\n', start)
    if line_end == -1:
        line_end = len(query)
    line_text = query[line_start:line_end]
    line_no = query.count('\n', 0, line_start) + 1
    col = start - line_start
    gutter = len(str(line_no))
    pad_top = ' ' * gutter + ' |'
    lines = []
    lines.append('error: %s' % title)
    lines.append(pad_top)
    lines.append('%d | %s' % (line_no, line_text))
    carets = '^' * max(length, 0)
    lab = (' ' + label) if label else ''
    lines.append(pad_top + ' ' + ' ' * col + carets + lab)
    lines.append(pad_top)
    for h in helps:
        lines.append('  = help: %s' % h)
    return '\n'.join(lines) + '\n'

def parse_fail(query, title, start, length, label=None, helps=(), final=None):
    text = rich_report(query, title, start, length, label, helps)
    text += final if final is not None else 'Error: Failed to parse query\n'
    raise ParseFailure(text)

def simple_parse_fail():
    raise ParseFailure('Error: Failed to parse query\n')

# Did-you-mean (Jaro-Winkler, as used by clap/strsim)
def _jaro(s1, s2):
    if s1 == s2:
        return 1.0
    len1, len2 = len(s1), len(s2)
    if len1 == 0 or len2 == 0:
        return 0.0
    match_dist = max(len1, len2) // 2 - 1
    if match_dist < 0:
        match_dist = 0
    s1_matches = [False] * len1
    s2_matches = [False] * len2
    matches = 0
    for i in range(len1):
        lo = max(0, i - match_dist)
        hi = min(len2, i + match_dist + 1)
        for j in range(lo, hi):
            if not s2_matches[j] and s1[i] == s2[j]:
                s1_matches[i] = True; s2_matches[j] = True; matches += 1; break
    if matches == 0:
        return 0.0
    t = 0
    k = 0
    for i in range(len1):
        if s1_matches[i]:
            while not s2_matches[k]:
                k += 1
            if s1[i] != s2[k]:
                t += 1
            k += 1
    t //= 2
    return (matches/len1 + matches/len2 + (matches - t)/matches) / 3.0

def jaro_winkler(s1, s2):
    j = _jaro(s1, s2)
    prefix = 0
    for a, b in zip(s1, s2):
        if a == b and prefix < 4:
            prefix += 1
        else:
            break
    return j + prefix * 0.1 * (1 - j)

def did_you_mean(word, candidates):
    best = None; best_score = 0.8
    for c in candidates:
        sc = jaro_winkler(word, c)
        if sc > best_score:
            best_score = sc; best = c
    return best

