# Expression AST

class Expr:
    __slots__ = ('kind', 'args', 'span')
    def __init__(self, kind, args, span=(0, 0)):
        self.kind = kind; self.args = args; self.span = span
    def __repr__(self):
        return 'Expr(%s,%r)' % (self.kind, self.args)

KNOWN_FUNCTIONS = {
 'abs','acos','asin','atan','atan2','cbrt','ceil','cos','cosh','exp','expm1','floor',
 'hypot','log','log10','log1p','round','sin','sinh','sqrt','tan','tanh','toDegrees','toRadians',
 'concat','contains','length','now','num','parseDate','parseHex','substring',
 'toLowerCase','toUpperCase','isNull','isEmpty','isBlank','isNumeric'}
UNARY_MATH = {'abs','acos','asin','atan','cbrt','ceil','cos','cosh','exp','expm1','floor',
 'log','log10','log1p','round','sin','sinh','sqrt','tan','tanh','toDegrees','toRadians'}

_ESCAPES = {'n':'\n','t':'\t','r':'\r','0':'\0','\\':'\\',"'":"'",'"':'"'}

class Scanner:
    def __init__(self, text):
        self.s = text
        self.n = len(text)
        self.pos = 0
    def eof(self):
        return self.pos >= self.n
    def peek(self, off=0):
        p = self.pos + off
        return self.s[p] if p < self.n else ''
    def skip_ws(self):
        start = self.pos
        while self.pos < self.n and self.s[self.pos] in ' \t\n\r\x0b\x0c':
            self.pos += 1
        return self.pos - start
    def starts(self, txt):
        return self.s.startswith(txt, self.pos)

    def parse_string(self, ctx='expr'):
        q = self.s[self.pos]
        start = self.pos
        self.pos += 1
        out = []
        while self.pos < self.n:
            ch = self.s[self.pos]
            if ch == q:
                self.pos += 1
                return ''.join(out), start, self.pos
            if ch == '\\':
                if self.pos + 1 >= self.n:
                    break
                nx = self.s[self.pos+1]
                if nx in _ESCAPES:
                    out.append(_ESCAPES[nx])
                else:
                    out.append('\\'); out.append(nx)
                self.pos += 2
                continue
            out.append(ch)
            self.pos += 1
        raise ParseFailure('__unterminated_string__:%d:%d:%s' % (start, self.pos, ctx))

IDENT_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
INT_TOKEN_RE = re.compile(r'-?[0-9]+')

def parse_escaped_segment(sc):
    """At '['; parse ["..."] with no spaces. Return name or None."""
    save = sc.pos
    if sc.pos + 1 >= sc.n or sc.s[sc.pos+1] not in '"\'':
        return None
    sc.pos += 1
    try:
        name, _, _ = sc.parse_string()
    except ParseFailure:
        sc.pos = save
        return None
    if sc.peek() != ']':
        sc.pos = save
        return None
    sc.pos += 1
    return name

def parse_column_path(sc):
    """Parse a column reference starting at pos. Return Expr or None."""
    start = sc.pos
    parts = []
    if sc.peek() == '[':
        name = parse_escaped_segment(sc)
        if name is None:
            return None
        parts.append(('key', name))
    else:
        m = IDENT_RE.match(sc.s, sc.pos)
        if not m:
            return None
        parts.append(('key', m.group(0)))
        sc.pos = m.end()
    while True:
        if sc.peek() == '.':
            save = sc.pos
            sc.pos += 1
            if sc.peek() == '[':
                nm = parse_escaped_segment(sc)
                if nm is None:
                    sc.pos = save; break
                parts.append(('key', nm)); continue
            m = IDENT_RE.match(sc.s, sc.pos)
            if not m:
                sc.pos = save; break
            parts.append(('key', m.group(0)))
            sc.pos = m.end(); continue
        if sc.peek() == '[':
            save = sc.pos
            m = re.match(r'\[(-?[0-9]+)\]', sc.s[sc.pos:])
            if not m:
                break
            idx = rust_parse_i64(m.group(1))
            if idx is None:
                break
            parts.append(('index', idx, m.group(1)))
            sc.pos += m.end(); continue
        break
    return Expr('col', (parts,), (start, sc.pos))

DURATION_UNITS = [('ns', 1), ('us', 1000), ('ms', 1000**2), ('s', 1000**3),
                  ('m', 60*1000**3), ('h', 3600*1000**3), ('d', 86400*1000**3), ('w', 7*86400*1000**3)]
DURATION_SEG_RE = re.compile(r'([0-9]+)(ns|us|ms|s|m|h|d|w)')

def try_parse_duration_literal(sc, allow_negative=False):
    start = sc.pos
    pos = sc.pos
    neg = False
    if allow_negative and sc.s[pos:pos+1] == '-':
        neg = True; pos += 1
    total = 0
    count = 0
    p = pos
    while True:
        m = DURATION_SEG_RE.match(sc.s, p)
        if not m:
            break
        amount = rust_parse_i64(m.group(1))
        if amount is None:
            return None
        unit_ns = dict(DURATION_UNITS)[m.group(2)]
        total += amount * unit_ns
        count += 1
        p = m.end()
    if count == 0:
        return None
    if neg:
        total = -total
    sc.pos = p
    return Expr('lit', (DurationValue(total),), (start, p))

def expr_parse_error(sc, title, start, end=None):
    if end is None:
        end = sc.pos
    parse_fail(sc.s, title, start, max(end - start, 0))

class ExprParser:
    def __init__(self, sc):
        self.sc = sc

