    val = []
    in_value = False
    in_quote = False
    escaped = False
    has_eq = False
    i = 0
    n = len(text)
    def flush(end=False):
        nonlocal key, val, in_value, has_eq
        k = ''.join(key)
        if in_value:
            if k != '':
                if val or end:
                    record.data[k] = infer_value(''.join(val))
                # empty value mid-string: keep waiting (handled by caller logic)
        else:
            if k != '':
                record.data[k] = None
    while i < n:
        ch = text[i]
