def split_with_quotes(text, sep):
    toks = []
    cur = []
    i = 0
    n = len(text)
    in_quote = None
    quoted_token = False
    def emit():
        nonlocal cur, quoted_token
        raw = ''.join(cur)
        cur = []
        quoted_token = False
        if rust_trim(raw) != '':
            toks.append(infer_value(raw))
    while i < n:
        if in_quote is not None:
            ch = text[i]
            if ch == in_quote and (i == 0 or text[i-1] != '\\'):
                in_quote = None
                emit()
                i += 1; continue
            cur.append(ch); i += 1; continue
        if sep != '' and text.startswith(sep, i):
            emit()
            i += len(sep); continue
        ch = text[i]
        if ch in '"\'' and len(cur) == 0:
            in_quote = ch
            quoted_token = True
            cur.append('\x00QUOTE\x00')
            i += 1; continue
        cur.append(ch); i += 1
    if in_quote is not None:
        # unmatched quote: the opening quote is retained
        raw = ''.join(cur)
        raw = raw.replace('\x00QUOTE\x00', in_quote, 1)
        if rust_trim(raw) != '':
            toks.append(infer_value(raw))
    else:
        # strip quote markers from a trailing token if any (cannot happen: a
        # matched quote emits immediately) then emit
        emit()
    # Clean up quote markers accidentally retained (defensive)
    return toks

