def as_string_value(v):
    if isinstance(v, str):
        return v
    if v is None:
        raise EvalError('Found None, expected String')
    raise EvalError('Expected string, found other')

class Op:
    kind = 'inline'
    def apply_record(self, rec):
        return rec
    def new_state(self):
        return None

def _source_text(rec, expr):
    if expr is None:
        return rec.raw
    v = eval_expr(expr, rec)
    return as_string_value(v)

class JsonOp(Op):
    def __init__(self, from_expr=None):
        self.from_expr = from_expr
