        text = _source_text(rec, self.from_expr)
        try:
            v = parse_json_text(text)
        except Exception:
            raise EvalError('Expected JSON, found %s' % text)
        if isinstance(v, dict):
            for k, x in v.items():
                rec.data[k] = copy_value(x)
        return rec

