def set_at_column(rec, col_expr, value):
    """Set value at a (possibly nested) column path in a record."""
    parts = col_expr.args[0]
    first = parts[0][1]
    if len(parts) == 1:
        rec.data[first] = copy_value(value)
        return
    if first not in rec.data:
        raise EvalError('No value for key %s' % rust_debug_str(first))
    cur = rec.data[first]
    for part in parts[1:-1]:
        if part[0] == 'key':
            if not isinstance(cur, dict):
                raise EvalError('Expected object, found %s' % render_value(cur))
            if part[1] not in cur:
                raise EvalError('No value for key %s' % rust_debug_str(part[1]))
            cur = cur[part[1]]
        else:
            if not isinstance(cur, list):
                raise EvalError('Expected array, found %s' % render_value(cur))
            j = part[1] if part[1] >= 0 else len(cur) + part[1]
            if j < 0 or j >= len(cur):
                raise EvalError('Index %d out of range' % part[1])
            cur = cur[j]
    last = parts[-1]
    if last[0] == 'key':
        if not isinstance(cur, dict):
            raise EvalError('Expected object, found %s' % render_value(cur))
        cur[last[1]] = copy_value(value)
    else:
        if not isinstance(cur, list):
            raise EvalError('Expected array, found %s' % render_value(cur))
        j = last[1] if last[1] >= 0 else len(cur) + last[1]
        if j < 0 or j >= len(cur):
            raise EvalError('Index %d out of range' % last[1])
        cur[j] = copy_value(value)

