class ParseGlobOp(Op):
    def __init__(self, pattern, fields, from_expr=None, nodrop=False, noconvert=False):
        self.pattern = pattern
        self.fields = fields
        self.from_expr = from_expr
        self.nodrop = nodrop
        self.noconvert = noconvert
        self.segments = pattern.split('*')
    def _find_segment(self, text, seg, pos):
        # find seg (where ' ' matches any single whitespace char) from pos
        if seg == '':
            return (pos, pos)
        i = pos
        last = len(text) - len(seg)
        while i <= last:
            ok = True
            for j, pc in enumerate(seg):
                tc = text[i+j]
                if pc == ' ':
                    if tc not in ' \t\n\r\x0b\x0c' and not tc.isspace():
                        ok = False; break
                elif pc != tc:
                    ok = False; break
            if ok:
                return (i, i + len(seg))
            i += 1
        return None
    def match(self, text):
        segs = self.segments
        caps = []
        found = self._find_segment(text, segs[0], 0)
        if found is None:
            return None
        pos = found[1]
        if len(segs) == 1:
            return caps
        for seg in segs[1:]:
            if seg == '':
                # last segment empty only has meaning at the end; for a middle
                # empty segment, capture is empty and we continue.
                if seg is segs[-1]:
                    caps.append(text[pos:])
                    pos = len(text)
                else:
                    caps.append('')
                continue
            f = self._find_segment(text, seg, pos)
            if f is None:
                return None
            caps.append(text[pos:f[0]])
            pos = f[1]
        # Pattern ends with '*': segments end with '', handled above. If the
        # final segment is non-empty we already captured segs-1 values.
        if segs[-1] != '':
            pass
        # Number of captures must equal number of stars; if trailing star was
        # not final?? (segments count = stars+1). When segs[-1]=='', the loop
        # appended the final capture. Adjust length.
        nstars = len(segs) - 1
        if len(caps) < nstars:
            caps.append(text[pos:])
        return caps[:nstars]
    def apply_record(self, rec):
        text = _source_text(rec, self.from_expr)
        caps = self.match(text)
        if caps is None:
            if self.nodrop:
                for f in self.fields:
                    rec.data[f] = None
                return rec
            return None
        for f, cap in zip(self.fields, caps):
            rec.data[f] = cap if self.noconvert else infer_value(cap)
        return rec

class ParseRegexOp(Op):
    def __init__(self, regex, names, from_expr=None, nodrop=False, noconvert=False):
        self.regex = regex
        self.names = names
        self.from_expr = from_expr
        self.nodrop = nodrop
        self.noconvert = noconvert
    def apply_record(self, rec):
        text = _source_text(rec, self.from_expr)
        m = self.regex.search(text)
        if not m:
            if self.nodrop:
                for nm in self.names:
                    rec.data[nm] = None
                return rec
            return None
        for idx, nm in enumerate(self.names):
            v = m.group(idx + 1)
            if v is None:
                rec.data[nm] = None
            else:
                rec.data[nm] = v if self.noconvert else infer_value(v)
        return rec

