class AggFunc:
    def __init__(self, kind, expr, pct, out_name):
        self.kind = kind; self.expr = expr; self.pct = pct; self.out_name = out_name
    def make_state(self):
        if self.kind == 'count':
            return [0]
        if self.kind == 'sum':
            return [0.0]
        if self.kind == 'average':
            return [0.0, 0]
        if self.kind in ('min', 'max'):
            return [None]
        if self.kind == 'pct':
            return [[]]
        if self.kind == 'count_distinct':
            return [set()]
        return [None]
    def update(self, st, rec):
        if self.kind == 'count' and self.expr is None:
            st[0] += 1
            return
        try:
            v = eval_expr(self.expr, rec)
        except EvalError:
            return
        if self.kind == 'count':
            if v is True:
                st[0] += 1
            return
        if self.kind == 'count_distinct':
            st[0].add(encode_hashable(v))
            return
        num = agg_number(v)
        if num is None:
            return
        f = to_f64(num)
        if self.kind == 'sum':
            st[0] += f
        elif self.kind == 'average':
            st[0] += f; st[1] += 1
        elif self.kind == 'min':
            if st[0] is None or f < st[0]:
                st[0] = f
        elif self.kind == 'max':
            if st[0] is None or f > st[0]:
                st[0] = f
        elif self.kind == 'pct':
            st[0].append(f)
    def result(self, st):
        if self.kind == 'count':
            return st[0]
        if self.kind == 'sum':
            return normalize_float(st[0])
        if self.kind == 'average':
            if st[1] == 0:
                return math.nan
            return normalize_float(st[0] / st[1])
        if self.kind in ('min', 'max'):
            return None if st[0] is None else normalize_float(st[0])
        if self.kind == 'pct':
            vals = st[0]
            if not vals:
                return None
            vals = sorted(vals, key=lambda x: (math.isnan(x), x))
            n = len(vals)
            # index = floor(q*n - 0.5), clamped
            idx = (2 * n * self.pct - 100) // 200
            if idx < 0: idx = 0
            if idx > n - 1: idx = n - 1
            return normalize_float(vals[idx])
        if self.kind == 'count_distinct':
            return len(st[0])
        return None

