# Format string (strfmt-like)

KNOWN_TYPE_CHARS = set('beEfFfoxX%?')

class FormatSpec:
    __slots__ = ('fill','align','width','precision','typ')
    def __init__(self):
        self.fill=' '; self.align='<'; self.width=None; self.precision=None; self.typ=None

def parse_format_spec(spec):
    fs = FormatSpec()
    i = 0; n = len(spec)
    if n >= 2 and spec[1] in '<>^=':
        fs.fill = spec[0]
        fs.align = spec[1]
        i = 2
        if fs.align == '=':
            raise StartupError("Error: Invalid(sign aware zero padding and Align '=' not yet supported)")
    elif n >= 1 and spec[0] in '<>^=':
        fs.align = spec[0]
        i = 1
        if fs.align == '=':
            raise StartupError("Error: Invalid(sign aware zero padding and Align '=' not yet supported)")
    if i < n and spec[i] in '+- ':
        raise StartupError('Error: TypeError(Sign not allowed in string format specifier)')
    if i < n and spec[i] == '#':
        raise StartupError('Error: TypeError(Alternate form (#) not allowed in string format specifier)')
    if i < n and spec[i] == '0' and i + 1 < n and spec[i+1].isdigit():
        raise StartupError("Error: Invalid(sign aware zero padding and Align '=' not yet supported)")
    m = re.match(r'[0-9]+', spec[i:])
    if m:
        fs.width = int(m.group(0)); i += m.end()
    if i < n and spec[i] == '.':
        i += 1
        m = re.match(r'[0-9]+', spec[i:])
        if not m:
            raise StartupError('Error: Invalid(Format specifier missing precision)')
        fs.precision = int(m.group(0)); i += m.end()
    if i < n:
        ch = spec[i]
        if ch == 's':
            fs.typ = 's'; i += 1
        elif ch in KNOWN_TYPE_CHARS:
            raise StartupError("Error: TypeError(Unknown format code Some('%s') for object of type 'str')" % ch)
        else:
            raise StartupError("Error: TypeError(Invalid type specifier: '%s')" % ch)
    if i != n:
        raise StartupError('Error: Invalid(Invalid format specifier)')
    return fs

def apply_format_spec(fs, s):
    if fs.precision is not None:
        s = ''.join(list(s)[:fs.precision])
    if fs.width is not None:
        chars = list(s)
        if len(chars) < fs.width:
            pad = fs.width - len(chars)
            if fs.align == '<':
                s = s + fs.fill * pad
            elif fs.align == '>':
                s = fs.fill * pad + s
            elif fs.align == '^':
                left = pad // 2
                right = pad - left
                s = fs.fill * left + s + fs.fill * right
    return s

class Formatter:
    def __init__(self, fmt):
        self.fmt = fmt
        self.parts = []  # ('lit', str) | ('field', name, FormatSpec)
        i = 0; n = len(fmt); lit = []
        def flush():
            if lit:
                self.parts.append(('lit', ''.join(lit))); lit.clear()
        while i < n:
            ch = fmt[i]
            if ch == '{':
                if i + 1 < n and fmt[i+1] == '{':
                    lit.append('{'); i += 2; continue
                flush()
                j = i + 1
                inner = []
                while j < n and fmt[j] != '}':
                    if fmt[j] == '{':
                        raise StartupError('Error: Invalid(extra { found)')
                    inner.append(fmt[j]); j += 1
                if j >= n:
                    raise StartupError("Error: Invalid(Expected '}' before end of string)")
                inner_s = ''.join(inner)
                if ':' in inner_s:
                    name, spec = inner_s.split(':', 1)
                else:
                    name, spec = inner_s, ''
                if name == '':
                    raise StartupError('Error: Invalid(must specify identifier)')
                fs = parse_format_spec(spec) if spec != '' else FormatSpec()
                self.parts.append(('field', name, fs))
                i = j + 1; continue
            if ch == '}':
                if i + 1 < n and fmt[i+1] == '}':
                    lit.append('}'); i += 2; continue
                raise StartupError("Error: Invalid(Single '}' encountered in format string)")
            lit.append(ch); i += 1
        flush()
    def render(self, values):
        out = []
        for part in self.parts:
            if part[0] == 'lit':
                out.append(part[1])
            else:
                _t, name, fs = part
                v = values.get(name, None)
                out.append(apply_format_spec(fs, render_value(v)))
        return ''.join(out)

