class WidthState:
    def __init__(self):
        self.widths = {}
    def update_inline(self, key, value_str):
        bl = len(value_str.encode('utf-8'))
        kl = len(key.encode('utf-8'))
        w = self.widths.get(key)
        if w is None:
            self.widths[key] = max(bl, kl)
        elif bl > w + 4:
            self.widths[key] = bl
    def update_table(self, name, cell_str):
        bl = len(cell_str.encode('utf-8'))
        kl = len(name.encode('utf-8'))
        w = self.widths.get(name)
        if w is None:
            self.widths[name] = max(bl, kl)
        elif bl > w + 4:
            self.widths[name] = bl

def _pad_chars(s, target):
    cl = len(s)
    if cl < target:
        return s + ' ' * (target - cl)
    return s

class Renderer:
    def __init__(self, mode, formatter=None, out=None):
        self.mode = mode  # legacy|json|logfmt|format
        self.formatter = formatter
        self.out = out
        self.inline_columns = []
        self.widths = WidthState()
    def write(self, text):
        b = (text + '\n').encode('utf-8', 'surrogatepass') if isinstance(text, str) else text
        try:
            self.out.write(b)
            self.out.flush()
        except (BrokenPipeError, OSError):
            raise BrokenPipeError()
    # -- inline records --
    def render_inline(self, rec):
        if self.mode == 'json':
            obj = '{' + ','.join('%s:%s' % (json_escape_str(k), json_value_str(rec.data[k])) for k in sorted(rec.data.keys())) + '}'
            self.write(obj); return
        if self.mode == 'logfmt':
            self.write(' '.join('%s=%s' % (k, render_value(rec.data[k])) for k in sorted(rec.data.keys()))); return
        if self.mode == 'format':
            self.write(self.formatter.render(dict(rec.data))); return
        # legacy
        if not rec.data:
            self.write(rec.raw); return
        # update column order/widths from this record's sorted keys
        rendered = {}
        for k in sorted(rec.data.keys()):
            if k not in self.inline_columns:
                self.inline_columns.append(k)
            vs = render_value(rec.data[k])
            rendered[k] = vs
            self.widths.update_inline(k, vs)
        present = [k for k in self.inline_columns if k in rec.data]
        parts = []
        for pi, k in enumerate(present):
            cell = '[%s=%s]' % (k, rendered[k])
            if pi == len(present) - 1:
                parts.append(cell)
            else:
                target = len(k.encode('utf-8')) + self.widths.widths[k] + 3 + 8
                seg = _pad_chars(cell, target)
                # missing columns between this and next present
                idx_here = self.inline_columns.index(k)
                idx_next = self.inline_columns.index(present[pi+1])
                extra = ''
                for mk in self.inline_columns[idx_here+1:idx_next]:
                    extra += ' ' * (len(mk.encode('utf-8')) + self.widths.widths.get(mk, len(mk.encode('utf-8'))) + 3 + 8)
                parts.append(seg + extra)
        self.write(''.join(parts))
    # -- aggregate dataset --
    def render_dataset(self, ds):
        if self.mode == 'json':
