    def op_parse(self):
        sc = self.sc
        # bare `parse` at very end is a no-op in the reference
        if sc.eof():
            return NoOp()
        sc.skip_ws()
        is_regex = False
        if self.word_at('regex'):
            sc.pos += 5
            is_regex = True
        pattern, pat_start, pat_end = self.parse_quoted()
        fields = []
        from_expr = None
        nodrop = False; noconvert = False
        seen_as = False; seen_from = False
        # phase 1: from / as in any order
        while True:
            sc.skip_ws()
            if sc.eof() or sc.peek() == '|':
                break
            if self.word_at('nodrop') or self.word_at('noconvert'):
                break
            if self.word_at('from') and not seen_from:
                sc.pos += 4; seen_from = True
                from_expr = self.parse_expr(); continue
            if self.word_at('as'):
                as_start = sc.pos
                if is_regex:
                    sc.pos += 2
                    sc.skip_ws()
                    # consume the name(s) for the span
                    nm_end = sc.pos
                    self.parse_simple_name()
                    parse_fail(self.text, "the parse regex operator does not support an 'as' clause",
                               as_start, sc.pos - as_start, 'remove this',
                               ["remove the 'as' clause, the named capture groups in the regular expression determine the output column"])
                if seen_as:
                    break
                seen_as = True
                sc.pos += 2
                # field list
                while True:
                    nm = self.parse_simple_name()
                    if nm is None:
                        start = as_start
                        end = self.segment_end()
                        parse_fail(self.text, "unrecognized option, only the 'from' and 'nodrop' options are available",
                                   as_start, max(len(rust_trim_end(self.text[as_start:end])), 0))
                    fields.append(nm)
                    sc.skip_ws()
                    if sc.peek() == ',':
                        sc.pos += 1; continue
                    break
                continue
            break
        # trailing: nodrop then noconvert
        if self.word_at('nodrop'):
            sc.pos += 6; nodrop = True
            sc.skip_ws()
        if self.word_at('noconvert'):
            sc.pos += 9; noconvert = True
        self.expect_end("unrecognized option, only the 'from' and 'nodrop' options are available")
        if is_regex:
            compiled, names = self._regex_transform(pattern, pat_start, pat_end - pat_start)
            return ParseRegexOp(compiled, names, from_expr, nodrop, noconvert)
        stars = pattern.count('*')
        if stars != len(fields):
            raise StartupError('Error: Wrong number of patterns for parse. Pattern has %d but %d were extracted' % (stars, len(fields)))
        return ParseGlobOp(pattern, fields, from_expr, nodrop, noconvert)

    def op_fields(self):
        sc = self.sc
        sc.skip_ws()
        if sc.eof() or sc.peek() == '|':
            return NoOp()
        mode = 'only'
        kw = False
        if self.word_at('only'):
            sc.pos += 4; mode = 'only'; kw = True
        elif self.word_at('except'):
            sc.pos += 6; mode = 'except'; kw = True
        names = []
        first = True
        while True:
            sc.skip_ws()
            if sc.eof() or sc.peek() == '|':
                break
            if first and sc.peek() in '+-':
                sign = sc.peek()
                if kw:
                    # e.g. "fields only -a" behaves as a no-op in reference
                    sc.pos = self.segment_end()
                    return NoOp()
                # sign alone
                save = sc.pos
                sc.pos += 1
                sc.skip_ws()
                if sc.eof() or sc.peek() == '|':
                    parse_fail(self.text, 'expecting an operand for binary operator', save, 1,
                               '- dangling binary operator', ['Add the operand or delete the operator'])
                mode = 'only' if sign == '+' else 'except'
            first = False
            # signed subsequent names keep the sign as part of the name
            signed = ''
            if names and sc.peek() in '+-':
                signed = sc.peek(); sc.pos += 1
                sc.skip_ws()
            save = sc.pos
            col = parse_column_path(sc)
            if col is None:
                if not names:
                    sc.pos = self.segment_end()
                    return NoOp()
                break
            names.append(signed + col.args[0][0][1])
            sc.skip_ws()
            if sc.peek() == ',':
                sc.pos += 1
                continue
            # anything else: reference ignores the rest of this segment and
            # truncates the remainder of the pipeline
            if not (sc.eof() or sc.peek() == '|'):
                self.truncate = True
                sc.pos = self.segment_end()
            break
        if not names:
            return NoOp()
        return FieldsOp(mode, names)

    def op_where(self):
        expr = self.parse_expr()
        e = unwrap(expr)
        if e.kind == 'lit' and not isinstance(e.args[0], bool):
            v = e.args[0]
            dbg = enum_debug(v)
            title = 'Expected boolean expression, found %s' % dbg
            text = rich_report(self.text, title, expr.span[0], expr.span[1] - expr.span[0],
                                 'This is constant',
                                 ['Perhaps you meant to compare a field to this value?',
                                  'example: where field1 == %s' % debug_value(v)])
            raise ParseFailure(text + 'Error: %s\n' % title)
        self.expect_end('unrecognized option, only the condition can be specified')
        return WhereOp(expr)

    def op_limit(self):
        sc = self.sc
        sc.skip_ws()
        if sc.eof() or sc.peek() == '|':
            return NoOp()
        if sc.peek() == '(':
            parse_fail(self.text, 'limit does not take any parenthesized arguments', sc.pos, 2)
        start = sc.pos
        end = self.segment_end()
        token = self.text[start:end].split()[0] if self.text[start:end].split() else ''
        if not re.fullmatch(r'[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)', token):
            parse_fail(self.text, 'unrecognized option, only the numeric limit can be specified',
                       start, max(len(rust_trim_end(self.text[start:end])), 0))
        sc.pos = start + len(token)
        self.expect_end('unrecognized option, only the numeric limit can be specified')
        # validate
        is_float = '.' in token
        if is_float:
            fv = float(token)
            if fv == 0:
                self._limit_bad(token, start, 'Zero is not allowed')
            if fv != math.trunc(fv):
                self._limit_bad(token, start, 'Fractional limits are not allowed')
            n = int(fv)
        else:
            try:
                n = int(token, 10)
            except Exception:
                n = I64_MAX if not token.startswith('-') else I64_MIN
            if n == 0:
                self._limit_bad(token, start, 'Zero is not allowed')
            if n > I64_MAX: n = I64_MAX
            if n < I64_MIN: n = I64_MIN
        return LimitOp(n)

    def _limit_bad(self, token, start, label):
        title = 'Limit must be a non-zero integer, found %s' % token
        text = rich_report(self.text, title, start, len(token), label,
                            ['Use a positive integer to select the first N rows',
                             'Use a negative integer to select the last N rows'])
        raise ParseFailure(text + 'Error: %s\n' % title)

    def op_sort(self):
        sc = self.sc
        sc.skip_ws()
        items = []
        if self.word_at('by'):
            sc.pos += 2
            while True:
                sc.skip_ws()
                if sc.eof() or sc.peek() == '|':
                    break
                expr = self.parse_expr()
                direction = None
                sc.skip_ws()
                for w, d in (('descending', True), ('ascending', False), ('desc', True), ('asc', False)):
                    if self.word_at(w):
                        sc.pos += len(w); direction = d; break
                items.append((expr, direction))
                sc.skip_ws()
                if sc.peek() == ',':
                    cpos = sc.pos
                    sc.pos += 1
                    sc.skip_ws()
                    if sc.eof() or sc.peek() == '|':
                        rep = rich_report(self.text, 'expecting an expression', cpos, 1)
                        raise ParseFailure(rep * 2 + 'Error: Failed to parse query\n')
                    continue
                if not (sc.eof() or sc.peek() == '|'):
                    # ignore rest of segment
                    sc.pos = self.segment_end()
                break
        else:
            sc.pos = self.segment_end()
        keys = []
        first_dir_idx = None; first_dir = False
        for i, (_e, d) in enumerate(items):
            if d is not None:
                first_dir_idx = i; first_dir = d; break
        for i, (e, d) in enumerate(items):
            desc = first_dir if (first_dir_idx is not None and i <= first_dir_idx) else False
            keys.append((e, desc))
        return SortOp(keys)

    def op_timeslice(self, token_end):
        sc = self.sc
        expr = self.paren_single_arg(token_end, '',
                    'expecting a parenthesized argument that supplies the date-time value for the log message')
        sc.skip_ws()
        if sc.eof() or sc.peek() == '|':
            raise StartupError('Error: Expected a duration for the timeslice (e.g. 1h)')
        dur_expr = try_parse_duration_literal(sc, allow_negative=True)
        if dur_expr is None:
            start = sc.pos
            parse_fail(self.text, "unrecognized option, only the 'as' option is available",
                       start, max(len(rust_trim_end(self.text[start:self.segment_end()])), 0))
        duration_ns = dur_expr.args[0].ns
        target = '_timeslice'
        sc.skip_ws()
        if self.word_at('as'):
            sc.pos += 2
            nm = self.parse_simple_name()
            if nm is None:
                self.expect_end("unrecognized option, only the 'as' option is available")
            else:
                target = nm
        self.expect_end("unrecognized option, only the 'as' option is available")
        return TimesliceOp(expr, duration_ns, target)

    def op_total(self, token_end):
        expr = self.paren_single_arg(token_end,
                    'the argument should supply the value to sum',
                    'expecting a parenthesized argument that supplies the value to sum')
        target = '_total'
        self.sc.skip_ws()
        if self.word_at('as'):
            self.sc.pos += 2
            nm = self.parse_simple_name()
            if nm is not None:
                target = nm
        self.expect_end("unrecognized option, only the 'as' option is available")
        return TotalOp(expr, target)

    # ---- aggregates ----
    def _agg_paren(self, name, token_start, phrase, help_arg):
        return self.paren_single_arg(token_start, help_arg, phrase)

    def parse_agg_func(self):
        sc = self.sc
        sc.skip_ws()
        start = sc.pos
        rest = sc.s[sc.pos:]
        name = None; kind = None; default_name = None; pct = None
        m = re.match(r'(?:percentile|pct|p)([0-9]+)', rest)
        # order matters: try named kinds before pct 'p' ambiguity (none start with p except parse)
        if rest.startswith('count_distinct'):
            name = 'count_distinct'; kind = 'count_distinct'; default_name = '_countDistinct'
            sc.pos += len('count_distinct')
            if sc.peek() != '(':
                parse_fail(self.text, 'Expecting an expression to count', start, max(sc.pos - start, 1))
            expr = self.paren_single_arg(start, '', 'Expecting an expression to count')
        elif rest.startswith('count'):
            name = 'count'; kind = 'count'; default_name = '_count'
            # count must be followed by '(' whitespace or segment boundary ( , | end)
            nxt = rest[5:6]
            if nxt and (nxt.isalnum() or nxt == '_'):
                raise _DiscardOp()
            sc.pos += 5
            if sc.peek() == '(':
                expr = self.paren_single_arg(start,
                        'the argument should supply the value to count',
                        'expecting a parenthesized argument')
            else:
                expr = None
        elif rest.startswith('average'):
            name = 'average'; kind = 'average'; default_name = '_average'; sc.pos += 7
            expr = self._agg_paren(name, start,
                'expecting a parenthesized argument that supplies the numeric value to find the average of', '')
        elif rest.startswith('avg'):
            name = 'avg'; kind = 'average'; default_name = '_average'; sc.pos += 3
            expr = self._agg_paren(name, start,
                'expecting a parenthesized argument that supplies the numeric value to find the average of', '')
        elif rest.startswith('sum'):
            name = 'sum'; kind = 'sum'; default_name = '_sum'; sc.pos += 3
            expr = self._agg_paren(name, start,
                'expecting a parenthesized argument that supplies the numeric value to find the sum of', '')
        elif rest.startswith('min'):
            name = 'min'; kind = 'min'; default_name = '_min'; sc.pos += 3
            expr = self._agg_paren(name, start,
                'expecting a parenthesized argument that supplies the numeric value to find the minimum of', '')
        elif rest.startswith('max'):
            name = 'max'; kind = 'max'; default_name = '_max'; sc.pos += 3
            expr = self._agg_paren(name, start,
                'expecting a parenthesized argument that supplies the numeric value to find the maximum of', '')
        elif m:
            pct = int(m.group(1))
            digits_span = (start + m.start(1), len(m.group(1)))
            name = m.group(0); kind = 'pct'; default_name = 'p%d' % pct
            sc.pos += m.end()
            if not (0 < pct < 100):
                parse_fail(self.text, 'invalid percentile number: %d' % pct,
                           digits_span[0], digits_span[1], 'expecting a number between (0, 100)')
            expr = self._agg_paren(name, start,
                'expecting a parenthesized argument that supplies the value to compute the percentile of', '')
        else:
            raise _DiscardOp()
        # optional rename
        out_name = default_name
        sc.skip_ws()
        if self.word_at('as'):
            sc.pos += 2
            nm = self.parse_simple_name()
            if nm is None:
                raise _DiscardOp()
            if sc.peek() in '.[':
                raise StartupError('Error: Unknown function %s' % name)
            out_name = nm
        return AggFunc(kind, expr, pct, out_name)

    def op_aggregate(self):
        funcs = []
        try:
            while True:
                funcs.append(self.parse_agg_func())
                self.sc.skip_ws()
                if self.sc.peek() == ',':
                    self.sc.pos += 1
                    continue
                break
            keys = []
            self.sc.skip_ws()
            if self.word_at('by'):
                self.sc.pos += 2
                while True:
                    self.sc.skip_ws()
                    if self.sc.eof() or self.sc.peek() == '|':
                        if not keys:
                            raise _DiscardOp()
                        rep = rich_report(self.text, 'expecting an expression', self.sc.pos - 1, 1)
                        raise ParseFailure(rep * 2 + 'Error: Failed to parse query\n')
                    e = self.parse_expr()
                    nm = self.text[e.span[0]:e.span[1]]
                    keys.append((e, nm))
                    self.sc.skip_ws()
                    if self.sc.peek() == ',':
                        self.sc.pos += 1
                        self.sc.skip_ws()
                        if self.sc.eof() or self.sc.peek() == '|':
                            rep = rich_report(self.text, 'expecting an expression', self.sc.pos - 1, 1)
                            raise ParseFailure(rep * 2 + 'Error: Failed to parse query\n')
                        continue
                    break
            self.sc.skip_ws()
            if not (self.sc.eof() or self.sc.peek() == '|'):
                raise _DiscardOp()
        except _DiscardOp:
            self.truncate = True
            self.sc.pos = self.segment_end()
            return None
        return GroupAggOp(funcs, keys)

    # ---- dispatch ----
    def _expected_operator_error(self, token, start):
        helps = ['%s is not a valid operator' % token]
        cands = list(STANDARD_OP_NAMES) + [k for k in self.aliases.keys() if k not in ('apache', 'nginx')]
        sug = did_you_mean(token, cands)
        if sug:
            helps.append('Did you mean "%s"?' % sug)
        parse_fail(self.text, 'Expected an operator', start, len(token), None, helps)

    def parse_one_operator(self):
        sc = self.sc
        sc.skip_ws()
        start = sc.pos
        if sc.eof():
            parse_fail(self.text, 'expecting an expression', max(start - 1, 0), 1)
        # aggregates by name prefix
        rest = sc.s[sc.pos:]
        m_ident = IDENT_RE.match(sc.s, sc.pos)
        word = m_ident.group(0) if m_ident else ''
        # standard operators (exact word)
        if word == 'json' or word == 'logfmt':
            sc.pos += len(word)
            return [self.op_json_logfmt(word)]
        if word == 'split':
            sc.pos += len(word)
            return [self.op_split(sc.pos)]
        if word == 'parse':
            sc.pos += len(word)
            return [self.op_parse()]
        if word == 'fields':
            sc.pos += len(word)
            return [self.op_fields()]
        if word == 'where':
            # "wherex" is where + garbage in the reference
            sc.pos += len(word)
            sc.skip_ws()
            if sc.eof() or sc.peek() == '|':
                parse_fail(self.text, 'Expected an expression', start, len(word))
            return [self.op_where()]
        if sc.starts('where') and len(word) > 5:
            parse_fail(self.text, 'unrecognized option, only the condition can be specified',
                       start + 5, 1)
        if word == 'limit':
            sc.pos += len(word)
            if sc.peek() == '(':
                parse_fail(self.text, 'limit does not take any parenthesized arguments', sc.pos - 1, 2)
            return [self.op_limit()]
        if word == 'sort' or (rest.startswith('sort') and word.startswith('sort')):
            # sort / sortx etc: match the identifier starting with sort
            if word.startswith('sort'):
                sc.pos += len(word)
                return [self.op_sort()]
        if word == 'timeslice':
            sc.pos += len(word)
            return [self.op_timeslice(sc.pos)]
        if word == 'total':
            sc.pos += len(word)
            return [self.op_total(sc.pos)]
        # aggregate functions
        if (word in ('count', 'sum', 'average', 'avg', 'min', 'max', 'count_distinct')
                or rest.startswith('sum') or rest.startswith('min') or rest.startswith('max')
                or rest.startswith('avg') or re.match(r'(?:percentile|pct|p)[0-9]+', rest)):
            op = self.op_aggregate()
            return [] if op is None else [op]
        # aliases (incl. apache / nginx)
        if word and word in self.aliases:
            sc.pos += len(word)
            return list(self.aliases[word])
        # try expression assignment
        save = sc.pos
        try:
            expr = self.parse_expr()
            sc.skip_ws()
            if self.word_at('as'):
                sc.pos += 2
                sc.skip_ws()
                tstart = sc.pos
                target = None
                if sc.peek() == '(':
                    te = self.parse_expr()
                    te = unwrap(te)
                    if te.kind == 'col':
                        target = te.args[0][0][1]
                else:
                    col = parse_column_path(sc)
                    if col is not None:
                        target = col.args[0][0][1]
                if target is None:
                    parse_fail(self.text, 'expecting a name for the field', tstart,
                               max(sc.pos - tstart, 1), None, ['Give the value a name'])
                # trailing junk truncates the pipeline in the reference
                sc.skip_ws()
                if not (sc.eof() or sc.peek() == '|'):
                    self.truncate = True
                    sc.pos = self.segment_end()
                return [ExprAssignOp(expr, target)]
        except StartupError:
            raise
        except ParseFailure:
            sc.pos = save
            # fall through to expected-operator errors below
        # Errors
        if word:
            # token for the message is the first column-ish token
            col = None
            save2 = sc.pos
            col = parse_column_path(sc)
            token_end = col.span[1] if col else start + len(word)
            # for a.b style, reference reports just "a"
            token = word
            sc.pos = save2
            self._expected_operator_error(token, start)
        ch = sc.peek()
        if ch == '[':
            col = parse_column_path(sc)
            token = self.text[start:col.span[1]] if col else '['
            self._expected_operator_error(token, start)
        if ch.isdigit() or ch in '.-+$(' or ch == '!':
            end = self.segment_end()
            length = len(rust_trim_end(self.text[start:end]))
            title = 'expecting an expression'
            if ch.isdigit():
                title = 'unrecognized syntax'
            parse_fail(self.text, title, start, length)
        parse_fail(self.text, 'expecting an expression', start, 1)

    def parse_operators(self):
        ops = []
        while True:
            self.sc.skip_ws()
            if self.sc.eof():
                break
            if self.sc.peek() != '|':
                simple_parse_fail()
            pipe_pos = self.sc.pos
            self.sc.pos += 1
            self.sc.skip_ws()
            if self.sc.eof():
                parse_fail(self.text, 'expecting an expression', pipe_pos, 1)
            new_ops = self.parse_one_operator()
            ops.extend(new_ops)
            self.partial_ops = ops
            if self.truncate:
                break
        return ops

    def parse_template_ops(self):
        ops = []
        first = True
        while True:
            self.sc.skip_ws()
            if self.sc.eof():
                break
            if not first:
                if self.sc.peek() != '|':
                    break
                self.sc.pos += 1
                self.sc.skip_ws()
                if self.sc.eof():
                    # trailing pipe: record an error like the reference
                    rep = rich_report(self.text, 'expecting an expression', max(self.sc.pos - 1, 0), 1)
                    self.template_errors.append(rep)
                    break
            first = False
            try:
                new_ops = self.parse_one_operator()
            except ParseFailure as ex:
                txt = ex.text
                if txt.endswith('Error: Failed to parse query\n'):
                    txt = txt[:-len('Error: Failed to parse query\n')]
                self.template_errors.append(txt)
                break
            ops.extend(new_ops)
            if self.truncate:
                break
        return ops

    def parse(self):
        # leading-whitespace-then-pipe quirk: whole query ignored
        if self.text[:1].isspace() and self.text.lstrip()[:1] == '|':
            return ('all',), []
        filt = self.parse_filters()
        ops = self.parse_operators()
        return filt, ops
