# ---------------------------------------------------------------------------
# Inline stream / dataset application

def apply_op_to_record(op, rec, report=True):
    try:
        return op.apply_record(rec)
    except EvalError as ex:
        if report:
            CTX.error(ex.args[0] if ex.args else str(ex))
        return None

def total_apply(op, records, acc):
    for rec in records:
        try:
            v = eval_expr(op.expr, rec)
            num = agg_number(v)
            if num is not None:
                acc += to_f64(num)
        except EvalError:
            pass
        rec.data[op.target] = normalize_float(acc)
        yield rec, acc

def apply_inline_dataset(op, ds):
    # column bookkeeping
    new_cols = []
    if isinstance(op, ExprAssignOp):
        new_cols.append(op.target_root)
    elif isinstance(op, TimesliceOp):
        new_cols.append(op.target)
    elif isinstance(op, TotalOp):
        new_cols.append(op.target)
    elif isinstance(op, ParseGlobOp):
        new_cols.extend(op.fields)
    elif isinstance(op, ParseRegexOp):
        new_cols.extend(op.names)
    elif isinstance(op, SplitOp):
        t = op.as_expr if op.as_expr is not None else op.arg_expr
        if t is None:
            new_cols.append('_split')
        else:
            te = unwrap(t)
            if te.kind == 'col':
                new_cols.append(te.args[0][0][1])
    for c in new_cols:
        if c not in ds.columns:
            ds.columns.append(c)
    out_rows = []
    if isinstance(op, TotalOp):
        acc = 0.0
        for rec in ds.rows:
            for r, acc in total_apply(op, [rec], acc):
                out_rows.append(r)
    else:
        for rec in ds.rows:
            r = rec.clone()
            res = apply_op_to_record(op, r, report=False)
            if res is not None:
                out_rows.append(res)
    ds.rows = out_rows
    if isinstance(op, FieldsOp) and op.mode:
        if op.mode == 'only':
            keep = set(op.names)
            ds.columns = [c for c in ds.columns if c in keep]
        else:
            drop = set(op.names)
            ds.columns = [c for c in ds.columns if c not in drop]
    elif isinstance(op, (JsonOp, LogfmtOp)):
        for rec in ds.rows:
            for k in sorted(rec.data.keys()):
                if k not in ds.columns:
                    ds.columns.append(k)

def scan_columns(rows):
    cols = []
    for rec in rows:
        for k in sorted(rec.data.keys()):
            if k not in cols:
                cols.append(k)
    return cols

# ---------------------------------------------------------------------------
# Filters

BARE_FILTER_CHARS = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789#$%*+-./:@^_')

def _star_node():
    return ('star',)

def _combine(kind, a, b):
    if a == ('star',):
        return b
    if b == ('star',):
        return a
    return (kind, a, b)

def match_filter(node, raw, raw_lower):
    k = node[0]
    if k == 'all' or k == 'star':
        return True
    if k == 'exact':
        needle = rust_trim_end(node[1])
        return needle in raw
    if k == 'wild':
        pos = 0
        for seg in node[1]:
            if seg == '':
                continue
            idx = raw_lower.find(seg, pos)
            if idx < 0:
                return False
            pos = idx + len(seg)
        return True
    if k == 'and':
        return match_filter(node[1], raw, raw_lower) and match_filter(node[2], raw, raw_lower)
    if k == 'or':
        return match_filter(node[1], raw, raw_lower) or match_filter(node[2], raw, raw_lower)
    if k == 'not':
        return not match_filter(node[1], raw, raw_lower)
    return True

class _FilterFail(Exception):
    pass

# ---------------------------------------------------------------------------
# Query parser

AGG_NAMES = ['count', 'sum', 'average', 'avg', 'min', 'max', 'count_distinct']
STANDARD_OP_NAMES = ['json', 'logfmt', 'split', 'parse', 'fields', 'where', 'limit',
                     'sort', 'timeslice', 'total', 'count', 'sum', 'average', 'avg',
                     'min', 'max', 'count_distinct']

class _DiscardOp(Exception):
    pass

class QueryParser:
    def __init__(self, text, aliases=None, template_mode=False):
        self.sc = Scanner(text)
        self.text = text
        self.aliases = aliases or {}
        self.template_mode = template_mode
        self.truncate = False
        self.partial_ops = []
        self.template_errors = []

    # ---- filters ----
    def _string_or_fail(self, filter_ctx=True):
        sc = self.sc
        start = sc.pos
        q = sc.peek()
        try:
            val, st, en = sc.parse_string()
            return val
        except ParseFailure:
            if filter_ctx:
                name = 'double' if q == '"' else 'single'
                rep = rich_report(self.text, 'unterminated %s quoted string' % name,
                                   start, sc.pos - start, None,
                                   ['Insert a %s quote (%s) to terminate this string' % (name, q)])
                raise ParseFailure(rep * 4 + 'Error: Failed to parse query\n')
            raise

    def parse_filter_unit(self):
        sc = self.sc
        sc.skip_ws()
        ch = sc.peek()
        if ch == '(':
            start = sc.pos
            sc.pos += 1
            node = self.parse_filter_segment()
            sc.skip_ws()
            if sc.peek() != ')':
                if sc.eof() or sc.peek() == '|':
                    rep = rich_report(self.text, 'unterminated parenthesized filter',
                                       start, sc.pos - start, 'unterminated parenthesized filter',
                                       ['Insert a right parenthesis to terminate this filter'])
                    raise ParseFailure(rep * 4 + 'Error: Failed to parse query\n')
                rep = rich_report(self.text, 'unhandled input', sc.pos - 1,
                                   max(self._paren_end(sc.pos) - (sc.pos - 1), 0))
                raise ParseFailure(rep * 4 + 'Error: Failed to parse query\n')
            sc.pos += 1
            return node
        if ch in '"\'':
            val = self._string_or_fail(True)
            return ('exact', val)
        # NOT
        if sc.starts('NOT'):
            save = sc.pos
            after = sc.pos + 3
            if after < sc.n and sc.s[after] in ' \t\n\r':
                sc.pos = after
                sc.skip_ws()
                inner = self.parse_filter_unit()
                if inner == ('star',):
                    return ('all',)
                return ('not', inner)
            sc.pos = save
        # bare term
        start = sc.pos
        while sc.pos < sc.n and sc.s[sc.pos] in BARE_FILTER_CHARS:
            sc.pos += 1
        if sc.pos == start:
            raise _FilterFail()
        term = sc.s[start:sc.pos]
        if set(term) == {'*'}:
            return _star_node()
        return ('wild', tuple(term.lower().split('*')))

    def _paren_end(self, pos):
        j = self.text.find(')', pos)
        return j if j >= 0 else len(self.text)

    def _bool_op(self, word):
        sc = self.sc
        save = sc.pos
        skipped = sc.skip_ws()
        if skipped and sc.starts(word):
            after = sc.pos + len(word)
            if after < sc.n and sc.s[after] in ' \t\n\r':
                sc.pos = after
                sc.skip_ws()
                return True
        sc.pos = save
        return False

    def parse_filter_and_segment(self):
        left = self.parse_filter_unit()
        if self._bool_op('AND'):
            right = self.parse_filter_unit()
            return _combine('and', left, right)
        return left

    def parse_filter_segment(self):
        left = self.parse_filter_and_segment()
        if self._bool_op('OR'):
            right = self.parse_filter_and_segment()
            return _combine('or', left, right)
        return left

    def parse_filters(self):
        segments = []
        while True:
            self.sc.skip_ws()
            if self.sc.eof() or self.sc.peek() == '|':
                break
            try:
                seg = self.parse_filter_segment()
            except _FilterFail:
                simple_parse_fail()
            if seg != ('star',) and seg != ('all',):
                segments.append(seg)
        if not segments:
            return ('all',)
        node = segments[0]
        for s in segments[1:]:
            node = ('and', node, s)
        return node

    # ---- helpers ----
    def segment_end(self, pos=None):
        s = self.text
        i = self.sc.pos if pos is None else pos
        depth = 0
        in_str = None
        esc = False
        while i < len(s):
            ch = s[i]
            if in_str:
                if esc:
                    esc = False
                elif ch == '\\':
                    esc = True
                elif ch == in_str:
                    in_str = None
                i += 1; continue
            if ch in '"\'':
                in_str = ch
            elif ch in '([':
                depth += 1
            elif ch in ')]':
                if depth > 0: depth -= 1
            elif ch == '|' and depth == 0:
                if i + 1 < len(s) and s[i+1] == '|':
                    i += 2; continue
                if i > 0 and s[i-1] == '|':
                    i += 1; continue
                return i
            i += 1
        return len(s)

    def at_segment_end(self):
        self.sc.skip_ws()
        return self.sc.eof() or (self.sc.peek() == '|' )

    def expect_end(self, options_msg):
        self.sc.skip_ws()
        if self.sc.eof() or self.sc.peek() == '|':
            return
        start = self.sc.pos
        # span to segment end, rtrim
        end = self.segment_end()
        seg = self.text[start:end]
        length = len(rust_trim_end(seg))
        if self.template_mode:
            rep = rich_report(self.text, options_msg, start, length)
            self.template_errors.append(rep)
            self.sc.pos = end
            self.truncate = True
            return
        parse_fail(self.text, options_msg, start, length)

    def word_at(self, word):
        sc = self.sc
        if sc.starts(word):
            after = sc.pos + len(word)
            if after >= sc.n or not (sc.s[after].isalnum() or sc.s[after] == '_'):
                return True
        return False

    def consume_word(self, word):
        self.sc.skip_ws()
        if self.word_at(word):
            self.sc.pos += len(word)
            return True
        return False

    def parse_simple_name(self):
        sc = self.sc
        sc.skip_ws()
        start = sc.pos
        if sc.peek() == '[':
            nm = parse_escaped_segment(sc)
            if nm is not None:
                return nm
            return None
        m = IDENT_RE.match(sc.s, sc.pos)
        if m:
            sc.pos = m.end()
            return m.group(0)
        return None

    def parse_expr(self):
        return ExprParser(self.sc).parse()

    def parse_quoted(self, what_start=None):
        sc = self.sc
        sc.skip_ws()
        # original expects whitespace before a quoted string in most spots,
        # but adjacency after keywords is tolerated by our scanner.
        if sc.peek() in '"\'':
            start = sc.pos
            val = self._string_or_fail(False)
            return val, start, sc.pos
        start = sc.pos
        end = self.segment_end()
        parse_fail(self.text, 'expecting a quoted string', start,
                   max(len(rust_trim_end(self.text[start:end])), 0), None,
                   ['Enclose the text in a single or double-quoted string'])

    def paren_single_arg(self, token_start, takes_help, missing_title):
        sc = self.sc
        start_of_arg_area = sc.pos
        if sc.peek() != '(':
            parse_fail(self.text, missing_title, sc.pos, max(self.segment_end() - sc.pos, 0))
        sc.pos += 1
        sc.skip_ws()
        if sc.peek() == ')':
            # "this operator takes 1 argument, but 0 were supplied"
            text = rich_report(self.text,
                'this operator takes 1 argument, but 0 were supplied',
                token_start, 0, None, [])
            # rebuild in the observed style
            lines = text.splitlines()
            rep = ('error: this operator takes 1 argument, but 0 were supplied\n'
                   '  |\n'
                   '1 | %s\n'
                   '  | %s- supplied 0 arguments\n'
                   '  |\n'
                   '  = help: %s\n' % (self.text.split('\n')[0], ' ' * token_start, takes_help))
            raise ParseFailure(rep + 'Error: Failed to parse query\n')
        expr = self.parse_expr()
        sc.skip_ws()
        if sc.peek() == ',':
            start = sc.pos
            end = self.text.find(')', sc.pos)
            if end < 0: end = sc.pos + 1
            parse_fail(self.text, 'unhandled input', start, max(end - start, 1))
        if sc.peek() != ')':
            parse_fail(self.text, 'unhandled input', sc.pos, 1)
        sc.pos += 1
        return expr

    # ---- individual operators ----
    def op_json_logfmt(self, which):
        from_expr = None
        self.sc.skip_ws()
        if not self.at_segment_end():
            if self.consume_word('from'):
                save = self.sc.pos
                self.sc.skip_ws()
                if self.sc.eof() or self.sc.peek() == '|':
                    kind = 'a JSON-encoded string' if which == 'json' else 'a logfmt-serialized string'
                    # span over the word 'from'
                    parse_fail(self.text, 'expecting an expression that supplies %s' % kind,
                               save - 4, 4, 'should be followed by an expression')
                from_expr = self.parse_expr()
            else:
                start = self.sc.pos
                end = self.segment_end()
                parse_fail(self.text, "unrecognized option, only the 'from' option is available",
                           start, max(len(rust_trim_end(self.text[start:end])), 0))
        self.expect_end("unrecognized option, only the 'from' option is available")
        return JsonOp(from_expr) if which == 'json' else LogfmtOp(from_expr)

    def op_split(self, token_end):
        sc = self.sc
        arg = None; sep = ','; as_expr = None
        if sc.peek() == '(':
            arg = self.paren_single_arg(token_end,
                    'the argument should supply the string to split',
                    'expecting a parenthesized argument')
        seen = set()
        while True:
            sc.skip_ws()
            if sc.eof() or sc.peek() == '|':
                break
            if self.word_at('on') and 'on' not in seen:
                sc.pos += 2; seen.add('on')
                val, _s, _e = self.parse_quoted()
                sep = val; continue
            if self.word_at('as') and 'as' not in seen:
                sc.pos += 2; seen.add('as')
                as_expr = self.parse_expr(); continue
            self.expect_end("unrecognized option, only the 'on' and 'as' options are available")
            break
        return SplitOp(arg, sep, as_expr)

    def _regex_transform(self, pattern, pat_start, pat_len):
        # Returns (compiled, [names]) ; raises ParseFailure in original style
        def fail(caret_pos, msg):
            label = 'regex parse error:\n    %s\n    %s^\nerror: %s' % (pattern, ' ' * caret_pos, msg)
            parse_fail(self.text, 'invalid regular expression', pat_start, pat_len, label)
        # reject lookaround / backreferences (Rust regex has none)
        for bad, msg in [('(?=', 'look-around is not supported'), ('(?!', 'look-around is not supported'),
                         ('(?<=', 'look-around is not supported'), ('(?<!', 'look-around is not supported')]:
            idx = pattern.find(bad)
            if idx >= 0:
                fail(idx, msg)
        names = []
        out = []
        i = 0; n = len(pattern); in_class = False
        def validate_name(name, name_start):
            if not name:
                fail(name_start, 'empty capture group name')
            for j, ch in enumerate(name):
                if j == 0:
                    ok = ch.isalpha() and ch.isascii() or ch == '_'
                else:
                    ok = (ch.isascii() and ch.isalnum()) or ch in '_.[]'
                if not ok:
                    fail(name_start + j, 'invalid capture group character')
        while i < n:
            ch = pattern[i]
            if ch == '\\' and i + 1 < n:
                nx = pattern[i+1]
                if nx == 'p':
                    # \pL or \p{...}
                    if i + 2 < n and pattern[i+2] == '{':
                        j = pattern.find('}', i + 3)
                        if j < 0:
                            fail(i, 'unclosed Unicode property')
                        prop = pattern[i+3:j]
                        adv = j + 1 - i
                    elif i + 2 < n:
                        prop = pattern[i+2]; adv = 3
                    else:
                        fail(i, 'unclosed Unicode property')
                    repl = {'L': '[^\\W\\d_]', 'Letter': '[^\\W\\d_]', 'Alphabetic': '[^\\W\\d_]',
                            'Nd': '\\d', 'N': '\\d', 'Whitespace': '\\s', 'White_Space': '\\s'}.get(prop)
                    if repl is None:
                        fail(i, 'unrecognised Unicode property')
                    if in_class:
                        repl = repl.strip('[]') if repl != '\\d' and repl != '\\s' else repl
                        if repl.startswith('^'):
                            repl = 'a-zA-Z'
                    out.append(repl); i += adv; continue
                if nx in '123456789':
                    fail(i, 'backreferences are not supported')
                out.append(pattern[i:i+2]); i += 2; continue
            if ch == '[' and not in_class:
                # POSIX classes
                m = re.match(r'\[\[:([a-z]+):\]\]', pattern[i:])
                if m:
                    repl = {'alpha': '[^\\W\\d_]', 'digit': '[0-9]', 'alnum': '[0-9A-Za-z]',
                            'space': '\\s', 'upper': '[A-Z]', 'lower': '[a-z]',
                            'xdigit': '[0-9A-Fa-f]', 'punct': '[^\\w\\s]', 'word': '\\w',
                            'blank': '[ \\t]', 'cntrl': '[\\x00-\\x1f\\x7f]', 'graph': '[^\\s]',
                            'print': '.'}.get(m.group(1))
                    if repl is None:
                        fail(i, 'unrecognised POSIX character class')
                    out.append(repl if repl.startswith('\\') or repl == '.' else repl)
                    i += m.end(); continue
                in_class = True; out.append(ch); i += 1; continue
            if ch == ']' and in_class:
                in_class = False; out.append(ch); i += 1; continue
            if ch == '(' and not in_class:
                m = re.match(r'\(\?P<([^>]*)>', pattern[i:])
                m2 = re.match(r'\(\?<([^>]*)>', pattern[i:]) if not m else None
                mm = m or m2
                if mm:
                    name = mm.group(1)
                    name_start = i + mm.start(1)
                    validate_name(name, name_start)
                    if name in names:
                        # duplicate: carets under both name starts
                        first = pattern.find('<' + name + '>')
                        caret_line = [' '] * (n + 1)
                        caret_line[first + 1] = '^'
                        caret_line[name_start] = '^'
                        label = 'regex parse error:\n    %s\n    %s\nerror: %s' % (pattern, ''.join(caret_line).rstrip(), 'duplicate capture group name')
                        parse_fail(self.text, 'invalid regular expression', pat_start, pat_len, label)
                    names.append(name)
                    out.append('(?P<g%d>' % (len(names) - 1))
                    i += mm.end(); continue
                out.append(ch); i += 1; continue
            out.append(ch); i += 1
        py_pat = ''.join(out)
        try:
            compiled = re.compile(py_pat, re.MULTILINE)
        except re.error as ex:
            msg = str(ex)
            pos = getattr(ex, 'pos', 0) or 0
            if 'unterminated character set' in msg or 'unterminated character' in msg:
                fail(pos, 'unclosed character class')
            if 'missing )' in msg or 'unterminated' in msg or 'unbalanced' in msg:
                fail(pos, 'unclosed group')
            if 'bad character range' in msg:
                fail(pos, 'invalid character class range')
            if 'nothing to repeat' in msg:
                fail(pos, 'repetition operator missing expression')
            if 'unknown extension' in msg or 'bad escape' in msg:
                fail(pos, 'unrecognised flag')
            fail(pos, msg)
        unnamed = compiled.groups - len(compiled.groupindex)
        if unnamed > 0:
            parse_fail(self.text, 'regular expression for the parse operator cannot have unnamed captures',
                       pat_start, pat_len, 'contains %d unnamed capture(s)' % unnamed,
                       ['name the capture groups by adding -- ?P<capname> -- right after the left parenthesis'])
        return compiled, names

    def op_parse(self):
        sc = self.sc
        # bare `parse` at very end is a no-op in the reference
        if sc.eof():
            return NoOp()
        sc.skip_ws()
        is_regex = False
        if self.word_at('regex'):
            sc.pos += 5
            is_regex = True
        pattern, pat_start, pat_end = self.parse_quoted()
        fields = []
        from_expr = None
        nodrop = False; noconvert = False
        seen_as = False; seen_from = False
        # phase 1: from / as in any order
        while True:
            sc.skip_ws()
            if sc.eof() or sc.peek() == '|':
                break
            if self.word_at('nodrop') or self.word_at('noconvert'):
                break
            if self.word_at('from') and not seen_from:
                sc.pos += 4; seen_from = True
                from_expr = self.parse_expr(); continue
            if self.word_at('as'):
                as_start = sc.pos
                if is_regex:
                    sc.pos += 2
                    sc.skip_ws()
                    # consume the name(s) for the span
                    nm_end = sc.pos
                    self.parse_simple_name()
                    parse_fail(self.text, "the parse regex operator does not support an 'as' clause",
                               as_start, sc.pos - as_start, 'remove this',
                               ["remove the 'as' clause, the named capture groups in the regular expression determine the output column"])
                if seen_as:
                    break
                seen_as = True
                sc.pos += 2
                # field list
                while True:
                    nm = self.parse_simple_name()
                    if nm is None:
                        start = as_start
                        end = self.segment_end()
                        parse_fail(self.text, "unrecognized option, only the 'from' and 'nodrop' options are available",
                                   as_start, max(len(rust_trim_end(self.text[as_start:end])), 0))
                    fields.append(nm)
                    sc.skip_ws()
                    if sc.peek() == ',':
                        sc.pos += 1; continue
                    break
                continue
            break
        # trailing: nodrop then noconvert
        if self.word_at('nodrop'):
            sc.pos += 6; nodrop = True
            sc.skip_ws()
        if self.word_at('noconvert'):
            sc.pos += 9; noconvert = True
        self.expect_end("unrecognized option, only the 'from' and 'nodrop' options are available")
        if is_regex:
            compiled, names = self._regex_transform(pattern, pat_start, pat_end - pat_start)
            return ParseRegexOp(compiled, names, from_expr, nodrop, noconvert)
        stars = pattern.count('*')
        if stars != len(fields):
            raise StartupError('Error: Wrong number of patterns for parse. Pattern has %d but %d were extracted' % (stars, len(fields)))
        return ParseGlobOp(pattern, fields, from_expr, nodrop, noconvert)

    def op_fields(self):
        sc = self.sc
        sc.skip_ws()
        if sc.eof() or sc.peek() == '|':
            return NoOp()
        mode = 'only'
        kw = False
        if self.word_at('only'):
            sc.pos += 4; mode = 'only'; kw = True
        elif self.word_at('except'):
            sc.pos += 6; mode = 'except'; kw = True
        names = []
        first = True
        while True:
            sc.skip_ws()
            if sc.eof() or sc.peek() == '|':
                break
            if first and sc.peek() in '+-':
                sign = sc.peek()
                if kw:
                    # e.g. "fields only -a" behaves as a no-op in reference
                    sc.pos = self.segment_end()
                    return NoOp()
                # sign alone
                save = sc.pos
                sc.pos += 1
                sc.skip_ws()
                if sc.eof() or sc.peek() == '|':
                    parse_fail(self.text, 'expecting an operand for binary operator', save, 1,
                               '- dangling binary operator', ['Add the operand or delete the operator'])
                mode = 'only' if sign == '+' else 'except'
            first = False
            # signed subsequent names keep the sign as part of the name
            signed = ''
            if names and sc.peek() in '+-':
                signed = sc.peek(); sc.pos += 1
                sc.skip_ws()
            save = sc.pos
            col = parse_column_path(sc)
            if col is None:
                if not names:
                    sc.pos = self.segment_end()
                    return NoOp()
                break
            names.append(signed + col.args[0][0][1])
            sc.skip_ws()
            if sc.peek() == ',':
                sc.pos += 1
                continue
            # anything else: reference ignores the rest of this segment and
            # truncates the remainder of the pipeline
            if not (sc.eof() or sc.peek() == '|'):
                self.truncate = True
                sc.pos = self.segment_end()
            break
        if not names:
            return NoOp()
        return FieldsOp(mode, names)

    def op_where(self):
        expr = self.parse_expr()
        e = unwrap(expr)
        if e.kind == 'lit' and not isinstance(e.args[0], bool):
            v = e.args[0]
            dbg = enum_debug(v)
            title = 'Expected boolean expression, found %s' % dbg
            text = rich_report(self.text, title, expr.span[0], expr.span[1] - expr.span[0],
                                 'This is constant',
                                 ['Perhaps you meant to compare a field to this value?',
                                  'example: where field1 == %s' % debug_value(v)])
            raise ParseFailure(text + 'Error: %s\n' % title)
        self.expect_end('unrecognized option, only the condition can be specified')
        return WhereOp(expr)

    def op_limit(self):
        sc = self.sc
        sc.skip_ws()
        if sc.eof() or sc.peek() == '|':
            return NoOp()
        if sc.peek() == '(':
            parse_fail(self.text, 'limit does not take any parenthesized arguments', sc.pos, 2)
        start = sc.pos
        end = self.segment_end()
        token = self.text[start:end].split()[0] if self.text[start:end].split() else ''
        if not re.fullmatch(r'[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)', token):
            parse_fail(self.text, 'unrecognized option, only the numeric limit can be specified',
                       start, max(len(rust_trim_end(self.text[start:end])), 0))
        sc.pos = start + len(token)
        self.expect_end('unrecognized option, only the numeric limit can be specified')
        # validate
        is_float = '.' in token
        if is_float:
            fv = float(token)
            if fv == 0:
                self._limit_bad(token, start, 'Zero is not allowed')
            if fv != math.trunc(fv):
                self._limit_bad(token, start, 'Fractional limits are not allowed')
            n = int(fv)
        else:
            try:
                n = int(token, 10)
            except Exception:
                n = I64_MAX if not token.startswith('-') else I64_MIN
            if n == 0:
                self._limit_bad(token, start, 'Zero is not allowed')
            if n > I64_MAX: n = I64_MAX
            if n < I64_MIN: n = I64_MIN
        return LimitOp(n)

    def _limit_bad(self, token, start, label):
        title = 'Limit must be a non-zero integer, found %s' % token
        text = rich_report(self.text, title, start, len(token), label,
                            ['Use a positive integer to select the first N rows',
                             'Use a negative integer to select the last N rows'])
