        if self.word_at('by'):
            sc.pos += 2
            while True:
                sc.skip_ws()
                if sc.eof() or sc.peek() == '|':
                    break
                expr = self.parse_expr()
                direction = None
                sc.skip_ws()
                for w, d in (('descending', True), ('ascending', False), ('desc', True), ('asc', False)):
                    if self.word_at(w):
                        sc.pos += len(w); direction = d; break
                items.append((expr, direction))
                sc.skip_ws()
                if sc.peek() == ',':
                    cpos = sc.pos
                    sc.pos += 1
                    sc.skip_ws()
                    if sc.eof() or sc.peek() == '|':
                        rep = rich_report(self.text, 'expecting an expression', cpos, 1)
                        raise ParseFailure(rep * 2 + 'Error: Failed to parse query\n')
                    continue
                if not (sc.eof() or sc.peek() == '|'):
                    # ignore rest of segment
                    sc.pos = self.segment_end()
                break
