        first_dir_idx = None; first_dir = False
        for i, (_e, d) in enumerate(items):
            if d is not None:
                first_dir_idx = i; first_dir = d; break
        for i, (e, d) in enumerate(items):
            desc = first_dir if (first_dir_idx is not None and i <= first_dir_idx) else False
            keys.append((e, desc))
