        elif rest.startswith('avg'):
            name = 'avg'; kind = 'average'; default_name = '_average'; sc.pos += 3
            expr = self._agg_paren(name, start,
                'expecting a parenthesized argument that supplies the numeric value to find the average of', '')
        elif rest.startswith('sum'):
            name = 'sum'; kind = 'sum'; default_name = '_sum'; sc.pos += 3
            expr = self._agg_paren(name, start,
                'expecting a parenthesized argument that supplies the numeric value to find the sum of', '')
        elif rest.startswith('min'):
            name = 'min'; kind = 'min'; default_name = '_min'; sc.pos += 3
            expr = self._agg_paren(name, start,
                'expecting a parenthesized argument that supplies the numeric value to find the minimum of', '')
        elif rest.startswith('max'):
            name = 'max'; kind = 'max'; default_name = '_max'; sc.pos += 3
            expr = self._agg_paren(name, start,
                'expecting a parenthesized argument that supplies the numeric value to find the maximum of', '')
        elif m:
            pct = int(m.group(1))
            digits_span = (start + m.start(1), len(m.group(1)))
            name = m.group(0); kind = 'pct'; default_name = 'p%d' % pct
