            self.sc.skip_ws()
            if self.word_at('by'):
                self.sc.pos += 2
                while True:
                    self.sc.skip_ws()
                    if self.sc.eof() or self.sc.peek() == '|':
                        if not keys:
                            raise _DiscardOp()
                        rep = rich_report(self.text, 'expecting an expression', self.sc.pos - 1, 1)
