    # ---- dispatch ----
    def _expected_operator_error(self, token, start):
        helps = ['%s is not a valid operator' % token]
        cands = list(STANDARD_OP_NAMES) + [k for k in self.aliases.keys() if k not in ('apache', 'nginx')]
        sug = did_you_mean(token, cands)
        if sug:
            helps.append('Did you mean "%s"?' % sug)
        parse_fail(self.text, 'Expected an operator', start, len(token), None, helps)

    def parse_one_operator(self):
        sc = self.sc
        sc.skip_ws()
        start = sc.pos
        if sc.eof():
            parse_fail(self.text, 'expecting an expression', max(start - 1, 0), 1)
        # aggregates by name prefix
        rest = sc.s[sc.pos:]
        m_ident = IDENT_RE.match(sc.s, sc.pos)
        word = m_ident.group(0) if m_ident else ''
        # standard operators (exact word)
        if word == 'json' or word == 'logfmt':
            sc.pos += len(word)
            return [self.op_json_logfmt(word)]
        if word == 'split':
            sc.pos += len(word)
            return [self.op_split(sc.pos)]
        if word == 'parse':
            sc.pos += len(word)
            return [self.op_parse()]
        if word == 'fields':
            sc.pos += len(word)
            return [self.op_fields()]
        if word == 'where':
            # "wherex" is where + garbage in the reference
            sc.pos += len(word)
            sc.skip_ws()
            if sc.eof() or sc.peek() == '|':
                parse_fail(self.text, 'Expected an expression', start, len(word))
            return [self.op_where()]
        if sc.starts('where') and len(word) > 5:
            parse_fail(self.text, 'unrecognized option, only the condition can be specified',
                       start + 5, 1)
        if word == 'limit':
            sc.pos += len(word)
            if sc.peek() == '(':
                parse_fail(self.text, 'limit does not take any parenthesized arguments', sc.pos - 1, 2)
            return [self.op_limit()]
        if word == 'sort' or (rest.startswith('sort') and word.startswith('sort')):
            # sort / sortx etc: match the identifier starting with sort
            if word.startswith('sort'):
                sc.pos += len(word)
                return [self.op_sort()]
        if word == 'timeslice':
            sc.pos += len(word)
            return [self.op_timeslice(sc.pos)]
        if word == 'total':
            sc.pos += len(word)
            return [self.op_total(sc.pos)]
        # aggregate functions
        if (word in ('count', 'sum', 'average', 'avg', 'min', 'max', 'count_distinct')
                or rest.startswith('sum') or rest.startswith('min') or rest.startswith('max')
                or rest.startswith('avg') or re.match(r'(?:percentile|pct|p)[0-9]+', rest)):
            op = self.op_aggregate()
            return [] if op is None else [op]
        # aliases (incl. apache / nginx)
        if word and word in self.aliases:
            sc.pos += len(word)
            return list(self.aliases[word])
        # try expression assignment
        save = sc.pos
        try:
            expr = self.parse_expr()
            sc.skip_ws()
            if self.word_at('as'):
                sc.pos += 2
                sc.skip_ws()
                tstart = sc.pos
                target = None
                if sc.peek() == '(':
                    te = self.parse_expr()
                    te = unwrap(te)
                    if te.kind == 'col':
                        target = te.args[0][0][1]
                else:
                    col = parse_column_path(sc)
                    if col is not None:
                        target = col.args[0][0][1]
                if target is None:
                    parse_fail(self.text, 'expecting a name for the field', tstart,
                               max(sc.pos - tstart, 1), None, ['Give the value a name'])
                # trailing junk truncates the pipeline in the reference
                sc.skip_ws()
                if not (sc.eof() or sc.peek() == '|'):
                    self.truncate = True
                    sc.pos = self.segment_end()
                return [ExprAssignOp(expr, target)]
        except StartupError:
            raise
        except ParseFailure:
            sc.pos = save
            # fall through to expected-operator errors below
        # Errors
        if word:
            # token for the message is the first column-ish token
            col = None
            save2 = sc.pos
            col = parse_column_path(sc)
            token_end = col.span[1] if col else start + len(word)
            # for a.b style, reference reports just "a"
            token = word
            sc.pos = save2
            self._expected_operator_error(token, start)
        ch = sc.peek()
        if ch == '[':
            col = parse_column_path(sc)
            token = self.text[start:col.span[1]] if col else '['
            self._expected_operator_error(token, start)
        if ch.isdigit() or ch in '.-+$(' or ch == '!':
            end = self.segment_end()
            length = len(rust_trim_end(self.text[start:end]))
            title = 'expecting an expression'
            if ch.isdigit():
                title = 'unrecognized syntax'
            parse_fail(self.text, title, start, length)
        parse_fail(self.text, 'expecting an expression', start, 1)

    def parse_operators(self):
        ops = []
        while True:
            self.sc.skip_ws()
            if self.sc.eof():
                break
            if self.sc.peek() != '|':
                simple_parse_fail()
            pipe_pos = self.sc.pos
            self.sc.pos += 1
            self.sc.skip_ws()
            if self.sc.eof():
                parse_fail(self.text, 'expecting an expression', pipe_pos, 1)
            new_ops = self.parse_one_operator()
            ops.extend(new_ops)
            self.partial_ops = ops
            if self.truncate:
                break
        return ops

    def parse_template_ops(self):
        ops = []
        first = True
        while True:
            self.sc.skip_ws()
            if self.sc.eof():
                break
            if not first:
                if self.sc.peek() != '|':
                    break
                self.sc.pos += 1
                self.sc.skip_ws()
                if self.sc.eof():
                    # trailing pipe: record an error like the reference
                    rep = rich_report(self.text, 'expecting an expression', max(self.sc.pos - 1, 0), 1)
                    self.template_errors.append(rep)
                    break
            first = False
            try:
                new_ops = self.parse_one_operator()
            except ParseFailure as ex:
                txt = ex.text
                if txt.endswith('Error: Failed to parse query\n'):
                    txt = txt[:-len('Error: Failed to parse query\n')]
                self.template_errors.append(txt)
                break
            ops.extend(new_ops)
            if self.truncate:
                break
        return ops

    def parse(self):
        # leading-whitespace-then-pipe quirk: whole query ignored
        if self.text[:1].isspace() and self.text.lstrip()[:1] == '|':
            return ('all',), []
        filt = self.parse_filters()
        ops = self.parse_operators()
        return filt, ops
