                    e = self.parse_expr()
                    nm = self.text[e.span[0]:e.span[1]]
                    keys.append((e, nm))
                    self.sc.skip_ws()
                    if self.sc.peek() == ',':
                        self.sc.pos += 1
                        self.sc.skip_ws()
