            # sort / sortx etc: match the identifier starting with sort
            if word.startswith('sort'):
                sc.pos += len(word)
                return [self.op_sort()]
        if word == 'timeslice':
            sc.pos += len(word)
            return [self.op_timeslice(sc.pos)]
        if word == 'total':
            sc.pos += len(word)
            return [self.op_total(sc.pos)]
        # aggregate functions
        if (word in ('count', 'sum', 'average', 'avg', 'min', 'max', 'count_distinct')
                or rest.startswith('sum') or rest.startswith('min') or rest.startswith('max')
                or rest.startswith('avg') or re.match(r'(?:percentile|pct|p)[0-9]+', rest)):
            op = self.op_aggregate()
