# Pipeline execution

def stream_records(lines, filt):
    for raw in lines:
        rec = Record(raw, {})
        if filt == ('all',) or match_filter(filt, raw, raw.lower()):
            yield rec

def apply_inline_stream(op, records, report_errors=True):
    if isinstance(op, LimitOp):
        n = op.n
        if n > 0:
            count = 0
            for rec in records:
                if count < n:
                    count += 1
                    yield rec
        else:
            keep = abs(n)
            buf = deque()
            for rec in records:
                buf.append(rec)
                while len(buf) > keep:
                    buf.popleft()
            for rec in buf:
                yield rec
        return
    if isinstance(op, TotalOp):
        acc = 0.0
        for rec in records:
            for r, acc in total_apply(op, [rec], acc):
                yield r
        return
    for rec in records:
        r = apply_op_to_record(op, rec, report=report_errors)
        if r is not None:
            yield r

def execute(ops, filt, lines, renderer):
    records = stream_records(lines, filt)
    mode = 'stream'
    pending_sort = None
    is_table = False
    ds = None
    pending_group = False  # a group result that hasn't been default-sorted
    CTX.suppress = False
    for op in ops:
        if mode == 'stream':
            if isinstance(op, SortOp):
                pending_sort = op
                is_table = True
                continue
            if isinstance(op, GroupAggOp):
                all_records = list(records)
                ds = group_apply(op, all_records)
                mode = 'dataset'
                is_table = True
                pending_group = True
                pending_sort = None
                continue
            records = apply_inline_stream(op, records, report_errors=True)
        else:
            if isinstance(op, GroupAggOp):
                if pending_group:
                    default_group_sort(ds)
                    pending_group = False
                ds = group_apply(op, list(ds.rows))
                pending_group = True
                continue
            if isinstance(op, SortOp):
                ds.rows = sort_rows(list(ds.rows), op.keys, ds.columns)
                pending_group = False
                continue
            if isinstance(op, LimitOp):
                if pending_group:
                    default_group_sort(ds)
                    pending_group = False
                n = op.n
                if n > 0:
                    ds.rows = ds.rows[:n]
                else:
                    ds.rows = ds.rows[n:] if abs(n) < len(ds.rows) else list(ds.rows)
                continue
            # inline op on dataset
            pending_group = False
            apply_inline_dataset(op, ds)
    if mode == 'stream':
        if is_table:
            rows = list(records)
            columns = scan_columns(rows)
            ds = Dataset(columns, rows)
            if pending_sort is not None:
                ds.rows = sort_rows(list(ds.rows), pending_sort.keys, columns)
            renderer.render_dataset(ds)
        else:
            for rec in records:
                renderer.render_inline(rec)
    else:
        if pending_group:
            default_group_sort(ds)
        renderer.render_dataset(ds)

