# ---------------------------------------------------------------------------
# Aliases

APACHE_PATTERN = '* - * [*] "* * *" * *'
NGINX_PATTERN = '* - * [*] "* * *" * * "*" "*" "*"'

def _builtin_aliases():
    apache = ParseGlobOp(APACHE_PATTERN,
        ['ip', 'name', 'timestamp', 'method', 'url', 'protocol', 'status', 'contentlength'])
    nginx = ParseGlobOp(NGINX_PATTERN,
        ['addr', 'user', 'timestamp', 'method', 'url', 'protocol', 'status', 'bytes_sent',
         'http_referer', 'http_user_agent', 'gzip_ratio'])
    return {'apache': [apache], 'nginx': [nginx]}

class TomlError(Exception):
    def __init__(self, line, col, span, msg, line_text):
        self.line = line; self.col = col; self.span = span; self.msg = msg; self.line_text = line_text

def _toml_parse(content):
    """Minimal TOML subset sufficient for alias files.
    Returns dict or raises TomlError."""
    result = {}
    lines = content.split('\n')
    i = 0
    # join multiline basic strings first by scanning
    # We parse line-oriented key = value with support for """...""" and '''...'''
    pos = 0
    n = len(content)
    def linecol(p):
        ls = content.rfind('\n', 0, p) + 1
        line_no = content.count('\n', 0, ls) + 1
        le = content.find('\n', ls)
        if le < 0: le = n
        return line_no, p - ls + 1, content[ls:le]
    while pos < n:
        # skip whitespace/comments/blank lines
        while pos < n and content[pos] in ' \t\r\n':
            pos += 1
        if pos < n and content[pos] == '#':
            while pos < n and content[pos] != '\n':
                pos += 1
            continue
        if pos >= n:
            break
        if content[pos] == '[':
            ln, cl, lt = linecol(pos)
            raise TomlError(ln, cl, 1, 'invalid table header', lt)
        m = re.match(r'[A-Za-z0-9_-]+', content[pos:])
        if not m:
            ln, cl, lt = linecol(pos)
            raise TomlError(ln, cl, 1, 'expected `.`, `=`', lt)
        key = m.group(0)
        key_end = pos + m.end()
        p = key_end
        while p < n and content[p] in ' \t':
            p += 1
        if p >= n or content[p] != '=':
            ln, cl, lt = linecol(p)
            raise TomlError(ln, cl, 1, 'expected `.`, `=`', lt)
        p += 1
        while p < n and content[p] in ' \t':
            p += 1
        val_start = p
        if content.startswith('"""', p) or content.startswith("'''", p):
            q = content[p:p+3]
            j = content.find(q, p + 3)
            if j < 0:
                ln, cl, lt = linecol(p)
                raise TomlError(ln, cl, 3, 'unterminated string', lt)
            raw = content[p+3:j]
            if raw.startswith('\n'):
                raw = raw[1:]
            value = _toml_unescape(raw) if q == '"""' else raw
            val_span = j + 3 - val_start
            pos = j + 3
        elif p < n and content[p] == '"':
            j = p + 1; buf = []
            while j < n and content[j] != '"':
                if content[j] == '\\' and j + 1 < n:
                    buf.append(content[j:j+2]); j += 2; continue
                if content[j] == '\n':
                    ln, cl, lt = linecol(p)
                    raise TomlError(ln, cl, 1, 'unterminated string', lt)
                buf.append(content[j]); j += 1
            if j >= n:
                ln, cl, lt = linecol(p)
                raise TomlError(ln, cl, 1, 'unterminated string', lt)
            value = _toml_unescape(''.join(buf))
            val_span = j + 1 - val_start
            pos = j + 1
        elif p < n and content[p] == "'":
            j = content.find("'", p + 1)
            if j < 0:
                ln, cl, lt = linecol(p)
                raise TomlError(ln, cl, 1, 'unterminated string', lt)
            value = content[p+1:j]
            val_span = j + 1 - val_start
            pos = j + 1
        else:
            m2 = re.match(r'[^\n#]*', content[p:])
            raw = m2.group(0).strip()
            val_span = len(raw)
            if re.fullmatch(r'[+-]?[0-9][0-9_]*', raw):
                value = int(raw.replace('_', ''))
            elif re.fullmatch(r'[+-]?([0-9][0-9_]*)?\.[0-9_]+([eE][+-]?[0-9]+)?', raw) or re.fullmatch(r'[+-]?[0-9][0-9_]*[eE][+-]?[0-9]+', raw):
                try:
                    value = ('float', float(raw.replace('_', '')))
                except Exception:
                    value = ('other', raw)
            elif raw in ('true', 'false'):
                value = ('bool', raw == 'true')
            else:
                ln, cl, lt = linecol(p)
                raise TomlError(ln, cl, max(val_span,1), 'invalid string\nexpected `.`, `=`', lt)
            pos = p + m2.end()
        if key in result:
            ln, cl, lt = linecol(pos)
            raise TomlError(ln, cl, 1, 'duplicate key `%s` in document root' % key, lt)
        result[key] = (value, val_start, val_span)
        # trailing comment to EOL
        while pos < n and content[pos] in ' \t':
            pos += 1
        if pos < n and content[pos] == '#':
            while pos < n and content[pos] != '\n':
                pos += 1
    return result, lines

def _toml_unescape(s):
    out = []
    i = 0
    mp = {'n':'\n','t':'\t','r':'\r','\\':'\\','"':'"','b':'\b','f':'\f'}
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            nx = s[i+1]
            if nx in mp:
                out.append(mp[nx]); i += 2; continue
            if nx == 'u' and i + 5 < len(s) + 1 and re.fullmatch(r'[0-9a-fA-F]{4}', s[i+2:i+6] or ''):
                try:
                    out.append(chr(int(s[i+2:i+6], 16))); i += 6; continue
                except Exception:
                    pass
            if nx == 'U' and re.fullmatch(r'[0-9a-fA-F]{8}', s[i+2:i+10] or ''):
                try:
                    out.append(chr(int(s[i+2:i+10], 16))); i += 10; continue
                except Exception:
                    pass
            if nx == '\n':
                i += 2
                while i < len(s) and s[i] in ' \t\n':
                    i += 1
                continue
            out.append('\\'); out.append(nx); i += 2; continue
        out.append(s[i]); i += 1
    return ''.join(out)

def _toml_type_name(v):
    if isinstance(v, bool):
        return 'boolean `%s`' % ('true' if v else 'false')
    if isinstance(v, int):
        return 'integer `%d`' % v
    if isinstance(v, tuple) and v and v[0] == 'float':
        return 'float `%s`' % v[1]
    if isinstance(v, tuple) and v and v[0] == 'bool':
        return 'boolean `%s`' % ('true' if v[1] else 'false')
    return 'string'

def _alias_warning(path, content, err):
    ln, cl, span, msg, lt = err.line, err.col, err.span, err.msg, err.line_text
    out = ('warning: invalid alias: TOML parse error at line %d, column %d\n'
           '  |\n%d | %s\n  | %s%s\n%s\n\n--> %s\n |\n |\n'
           % (ln, cl, ln, lt, ' ' * (cl - 1), '^' * max(span, 1), msg, path))
    sys.stderr.write(out)

def _load_alias_dir(dirpath, aliases, builtin_for_templates):
    try:
        entries = list(os.scandir(dirpath))
    except OSError as ex:
        raise StartupError('Error: %s (os error %d)' % (ex.strerror or str(ex), ex.errno or 2))
    for entry in entries:
        path = entry.path
        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as fh:
                content = fh.read()
        except OSError as ex:
            sys.stderr.write('warning: invalid alias: %s (os error %d)\n--> %s\n |\n |\n'
                             % (ex.strerror or str(ex), ex.errno or 0, path))
            continue
        try:
            table, lines = _toml_parse(content)
        except TomlError as ex:
            _alias_warning(path, content, ex)
            continue
        # struct validation
        first_line = lines[0] if lines else ''
        def missing(field):
            ln, lt = 1, first_line
            err = TomlError(ln, 1, len(lt), 'missing field `%s`' % field, lt)
            _alias_warning(path, content, err)
        if 'keyword' not in table:
            missing('keyword'); continue
        if 'template' not in table:
            missing('template'); continue
        kw_val, kw_pos, kw_span = table['keyword']
        tp_val, tp_pos, tp_span = table['template']
        bad = False
        for val, vpos, vspan in ((kw_val, kw_pos, kw_span), (tp_val, tp_pos, tp_span)):
            if not isinstance(val, str):
                ls = content.rfind('\n', 0, vpos) + 1
                ln = content.count('\n', 0, ls) + 1
                le = content.find('\n', ls)
                lt = content[ls:le if le >= 0 else len(content)]
                err = TomlError(ln, vpos - ls + 1, vspan,
                                'invalid type: %s, expected a string' % _toml_type_name(val), lt)
                _alias_warning(path, content, err)
                bad = True
                break
        if bad:
            continue
        keyword = kw_val
        template = tp_val
        # parse the template (errors printed, partial ops retained)
        if rust_trim(template) == '':
            sys.stderr.write('error: expecting an expression\n |\n |\n')
            ops = []
        else:
            qp = QueryParser(template, aliases=builtin_for_templates, template_mode=True)
            ops = qp.parse_template_ops()
            for e in qp.template_errors:
                sys.stderr.write(e)
        if keyword not in aliases:
            aliases[keyword] = ops

def load_aliases(alias_dir, no_alias):
    aliases = _builtin_aliases()
    builtin_for_templates = _builtin_aliases()
    if no_alias:
        return aliases
    user = {}
    if alias_dir is not None:
        _load_alias_dir(alias_dir, user, builtin_for_templates)
    else:
        cwd = os.getcwd()
        dirs = []
        d = cwd
        while True:
            dirs.append(d)
            parent = os.path.dirname(d)
            if parent == d:
                break
            d = parent
        for base in dirs:
            cand = os.path.join(base, '.agrind-aliases')
            if os.path.lexists(cand):
                _load_alias_dir(cand, user, builtin_for_templates)
    # user aliases override builtins (apache/nginx), first-seen already kept
    for k, v in user.items():
        aliases[k] = v
    return aliases

# ---------------------------------------------------------------------------
# Pipeline execution

def stream_records(lines, filt):
    for raw in lines:
        rec = Record(raw, {})
        if filt == ('all',) or match_filter(filt, raw, raw.lower()):
            yield rec

def apply_inline_stream(op, records, report_errors=True):
    if isinstance(op, LimitOp):
        n = op.n
        if n > 0:
            count = 0
            for rec in records:
                if count < n:
                    count += 1
                    yield rec
        else:
            keep = abs(n)
            buf = deque()
            for rec in records:
                buf.append(rec)
                while len(buf) > keep:
                    buf.popleft()
            for rec in buf:
                yield rec
        return
    if isinstance(op, TotalOp):
        acc = 0.0
        for rec in records:
            for r, acc in total_apply(op, [rec], acc):
                yield r
        return
    for rec in records:
        r = apply_op_to_record(op, rec, report=report_errors)
        if r is not None:
            yield r

def execute(ops, filt, lines, renderer):
    records = stream_records(lines, filt)
    mode = 'stream'
    pending_sort = None
    is_table = False
    ds = None
    pending_group = False  # a group result that hasn't been default-sorted
    CTX.suppress = False
    for op in ops:
        if mode == 'stream':
            if isinstance(op, SortOp):
                pending_sort = op
                is_table = True
                continue
            if isinstance(op, GroupAggOp):
                all_records = list(records)
                ds = group_apply(op, all_records)
                mode = 'dataset'
                is_table = True
                pending_group = True
                pending_sort = None
                continue
            records = apply_inline_stream(op, records, report_errors=True)
        else:
            if isinstance(op, GroupAggOp):
                if pending_group:
                    default_group_sort(ds)
                    pending_group = False
                ds = group_apply(op, list(ds.rows))
                pending_group = True
                continue
            if isinstance(op, SortOp):
                ds.rows = sort_rows(list(ds.rows), op.keys, ds.columns)
                pending_group = False
                continue
            if isinstance(op, LimitOp):
                if pending_group:
                    default_group_sort(ds)
                    pending_group = False
                n = op.n
                if n > 0:
                    ds.rows = ds.rows[:n]
                else:
                    ds.rows = ds.rows[n:] if abs(n) < len(ds.rows) else list(ds.rows)
                continue
            # inline op on dataset
            pending_group = False
            apply_inline_dataset(op, ds)
    if mode == 'stream':
        if is_table:
            rows = list(records)
            columns = scan_columns(rows)
            ds = Dataset(columns, rows)
            if pending_sort is not None:
                ds.rows = sort_rows(list(ds.rows), pending_sort.keys, columns)
            renderer.render_dataset(ds)
        else:
            for rec in records:
                renderer.render_inline(rec)
    else:
        if pending_group:
            default_group_sort(ds)
        renderer.render_dataset(ds)

# ---------------------------------------------------------------------------
# Input

def iter_lines(binary_stream):
    for raw_bytes in binary_stream:
        if raw_bytes.endswith(b'\n'):
            raw_bytes = raw_bytes[:-1]
        text = raw_bytes.decode('utf-8', 'replace')
        yield rust_trim_end(text)

