OPT_DEFS = {
 'f': ('--file', '<FILE>'), 'm': ('--format', '<FORMAT>'),
 'o': ('--output', '<OUTPUT>'), 'a': ('--alias-dir', '<ALIAS_DIR>'),
}
LONG_OPTS = {'--file': 'f', '--format': 'm', '--output': 'o', '--alias-dir': 'a',
             '--no-alias': None, '--help': 'h', '--version': 'V'}
LONG_NAMES = ['--file', '--format', '--output', '--alias-dir', '--no-alias', '--help', '--version']

class CliExit(Exception):
    def __init__(self, code, out='', err=''):
        self.code = code; self.out = out; self.err = err

def bin_name(argv0):
    base = os.path.basename(argv0) if argv0 else 'executable'
    return base or 'executable'

def _cli_error(bin_, msg, usage=None, tip=None):
    err = 'error: %s\n\n' % msg
    if tip:
        err += '  tip: %s\n\n' % tip
    err += 'Usage: %s\n\nFor more information, try \'--help\'.\n' % (usage or ('%s [OPTIONS] [QUERY]' % bin_))
    raise CliExit(2, '', err)

def _suggest_long(bin_, name):
    # name without leading dashes compared with long names (with dashes) as clap does
    best = None; best_score = 0.7
    for cand in LONG_NAMES:
        sc = jaro_winkler(name, cand)
        if sc > best_score:
            best_score = sc; best = cand
    return best

def parse_cli(argv):
    bin_ = bin_name(argv[0] if argv else 'executable')
    args = list(argv[1:])
    opts = {'file': None, 'format_m': None, 'output': None, 'alias_dir': None,
            'no_alias': False, 'query': None}
    seen = set()
    i = 0
    positional_only = False
    def set_query(val):
        if opts['query'] is not None:
            _cli_error(bin_, "unexpected argument '%s' found" % val)
        opts['query'] = val
    def record_value(key, flag_long, metavar, value):
        if key in seen:
            _cli_error(bin_, "the argument '%s %s' cannot be used multiple times" % (flag_long, metavar))
        seen.add(key)
        if key == 'a' and value == '':
            raise CliExit(2, '', "error: a value is required for '--alias-dir <ALIAS_DIR>' but none was supplied\n\nFor more information, try '--help'.\n")
        dest = {'f': 'file', 'm': 'format_m', 'o': 'output', 'a': 'alias_dir'}[key]
        opts[dest] = value
    def need_value(key, flag_long, metavar, attached, idx):
        # attached: string or None meaning take next argv
        if attached is not None:
            record_value(key, flag_long, metavar, attached)
            return idx
        if idx + 1 >= len(args):
            raise CliExit(2, '', "error: a value is required for '%s %s' but none was supplied\n\nFor more information, try '--help'.\n" % (flag_long, metavar))
        nxt = args[idx + 1]
        if nxt.startswith('-') and nxt != '-':
            raise CliExit(2, '', "error: a value is required for '%s %s' but none was supplied\n\nFor more information, try '--help'.\n" % (flag_long, metavar))
        record_value(key, flag_long, metavar, nxt)
        return idx + 1
    while i < len(args):
        arg = args[i]
        if positional_only:
            set_query(arg); i += 1; continue
        if arg == '--':
            positional_only = True; i += 1; continue
        if arg.startswith('--'):
            if '=' in arg:
                name, val = arg.split('=', 1)
            else:
                name, val = arg, None
            if name == '--help':
                if val is not None:
                    _cli_error(bin_, "unexpected value '%s' for '--help' found; no more were expected" % val,
                               '%s --help [QUERY]' % bin_)
                raise CliExit(0, LONG_HELP.format(bin=bin_), '')
            if name == '--version':
                if val is not None:
                    _cli_error(bin_, "unexpected value '%s' for '--version' found; no more were expected" % val,
                               '%s --version [QUERY]' % bin_)
                raise CliExit(0, VERSION + '\n', '')
            if name == '--no-alias':
                if val is not None:
                    _cli_error(bin_, "unexpected value '%s' for '--no-alias' found; no more were expected" % val,
                               '%s --no-alias [QUERY]' % bin_)
                if 'no-alias' in seen:
                    _cli_error(bin_, "the argument '--no-alias' cannot be used multiple times")
                seen.add('no-alias'); opts['no_alias'] = True; i += 1; continue
            if name in LONG_OPTS:
                key = LONG_OPTS[name]
                flag_long, metavar = OPT_DEFS[key]
                i = need_value(key, flag_long, metavar, val, i)
                i += 1; continue
            sug = _suggest_long(bin_, name)
            shown = name
            if opts['query'] is not None:
                _cli_error(bin_, "unexpected argument '%s' found" % shown,
                           '%s <QUERY>' % bin_, "to pass '%s' as a value, use '-- %s'" % (shown, shown))
            if sug:
                usage_map = {'--file': '--file <FILE>', '--format': '--format <FORMAT>',
                             '--output': '--output <OUTPUT>', '--alias-dir': '--alias-dir <ALIAS_DIR>',
                             '--no-alias': '--no-alias', '--help': '--help', '--version': '--version'}
                _cli_error(bin_, "unexpected argument '%s' found" % shown,
                           '%s %s [QUERY]' % (bin_, usage_map[sug]), "a similar argument exists: '%s'" % sug)
            _cli_error(bin_, "unexpected argument '%s' found" % shown, None,
                       "to pass '%s' as a value, use '-- %s'" % (shown, shown))
        if arg.startswith('-') and arg != '-':
            # short cluster
            j = 1
            consumed_next = False
            while j < len(arg):
                ch = arg[j]
                if ch == 'h':
                    raise CliExit(0, SHORT_HELP.format(bin=bin_), '')
                if ch == 'V':
                    raise CliExit(0, VERSION + '\n', '')
                if ch in OPT_DEFS:
                    flag_long, metavar = OPT_DEFS[ch]
                    rest = arg[j+1:]
                    if rest.startswith('='):
                        attached = rest[1:]
                    elif rest:
                        attached = rest
                    else:
                        attached = None
                    before = i
                    i = need_value(ch, flag_long, metavar, attached, i)
                    if i != before:
                        consumed_next = True
                    break
                shown = '-' + ch
                _cli_error(bin_, "unexpected argument '%s' found" % shown, None,
                           "to pass '%s' as a value, use '-- %s'" % (shown, shown))
            i += 1; continue
        set_query(arg)
        i += 1
    return opts

def io_debug_error(ex):
    kind_map = {1: 'PermissionDenied', 2: 'NotFound', 13: 'PermissionDenied',
                20: 'NotADirectory', 21: 'IsADirectory', 17: 'AlreadyExists',
                24: 'Uncategorized', 28: 'StorageFull', 32: 'BrokenPipe',
                4: 'Interrupted', 11: 'WouldBlock', 22: 'InvalidInput', 5: 'Uncategorized'}
    kind = kind_map.get(ex.errno or 0, 'Uncategorized')
    return 'Os { code: %d, kind: %s, message: "%s" }' % (ex.errno or 0, kind, ex.strerror or str(ex))

def main(argv):
    bin_ = bin_name(argv[0] if argv else 'executable')
    try:
        opts = parse_cli(argv)
    except CliExit as ex:
        if ex.out:
            sys.stdout.write(ex.out)
        if ex.err:
            sys.stderr.write(ex.err)
        return ex.code
    # Alias configuration is resolved before the missing-query check.
    if opts['no_alias'] and opts['alias_dir'] is not None:
        sys.stderr.write('Error: CantDisableAndOverride\n')
        return 1
    try:
        aliases = load_aliases(opts['alias_dir'], opts['no_alias'])
    except StartupError as ex:
        sys.stderr.write(ex.text if ex.text.endswith('\n') else ex.text + '\n')
        return 1
    if opts['query'] is None:
        sys.stderr.write('Error: MissingQuery\n')
        return 1
    query = opts['query']
    # Output mode resolution
    if opts['format_m'] is not None and opts['output'] is not None:
        sys.stderr.write('Error: CantSupplyBoth\n')
        return 1
    mode = 'legacy'
    fmt_str = None
    if opts['format_m'] is not None:
        mode = 'format'; fmt_str = opts['format_m']
    elif opts['output'] is not None:
        raw = opts['output']
        if '=' in raw:
            choice, param = raw.split('=', 1)
        else:
            choice, param = raw, None
        if choice == 'format':
            if param is None or param == '':
                sys.stderr.write('Error: InvalidFormatString\n')
                return 1
            mode = 'format'; fmt_str = param
        elif choice in ('legacy', 'json', 'logfmt'):
            if param is not None and param != '':
                sys.stderr.write('Error: InvalidOutputMode { choice: "%s", choices: "legacy, json, logfmt, format" }\n' % choice.replace('"', '\\"'))
                return 1
            mode = choice
        else:
            sys.stderr.write('Error: InvalidOutputMode { choice: "%s", choices: "legacy, json, logfmt, format" }\n' % choice.replace('"', '\\"'))
            return 1
    # Query parse
    try:
        qp = QueryParser(query, aliases=aliases)
        filt, ops = qp.parse()
    except ParseFailure as ex:
        sys.stderr.write(ex.text)
        return 1
    except StartupError as ex:
        sys.stderr.write(ex.text if ex.text.endswith('\n') else ex.text + '\n')
        return 1
    # Renderer (validates the format string)
    formatter = None
    if mode == 'format':
        try:
            if fmt_str is None or fmt_str == '':
                raise StartupError('Error: InvalidFormatString')
            formatter = Formatter(fmt_str)
        except StartupError as ex:
            sys.stderr.write(ex.text if ex.text.endswith('\n') else ex.text + '\n')
            return 1
    # Input
    stream = sys.stdin.buffer
    close_it = False
    if opts['file'] is not None:
        try:
            stream = open(opts['file'], 'rb')
            close_it = True
        except OSError as ex:
            sys.stderr.write('Error: %s\n' % io_debug_error(ex))
            return 1
    renderer = Renderer(mode, formatter, sys.stdout.buffer)
    try:
        execute(ops, filt, iter_lines(stream), renderer)
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        return 0
    finally:
        if close_it:
            try: stream.close()
            except Exception: pass
    return 0

if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        sys.exit(0)
    except KeyboardInterrupt:
        sys.exit(130)
