    def __init__(self, op):
        self.op = op
        self.groups = OrderedDict()
    def add(self, rec):
        op = self.op
        key_vals = []
        for expr, _nm in op.keys:
            try:
                key_vals.append(eval_expr(expr, rec))
            except EvalError:
                key_vals.append(None)
        enc = tuple(encode_hashable(v) for v in key_vals)
        ent = self.groups.get(enc)
        if ent is None:
            ent = (key_vals, [f.make_state() for f in op.funcs])
            self.groups[enc] = ent
        for f, st in zip(op.funcs, ent[1]):
            f.update(st, rec)
    def snapshot(self):
        op = self.op
        columns = [nm for _e, nm in op.keys] + [f.out_name for f in op.funcs]
        rows = []
        for key_vals, states in self.groups.values():
            data = {}
            for (_e, nm), v in zip(op.keys, key_vals):
                data[nm] = copy_value(v)
            for f, st in zip(op.funcs, states):
                data[f.out_name] = f.result(st)
            rows.append(Record('', data))
        ds = Dataset(columns, rows)
        ds.group_sort = ([f.out_name for f in op.funcs], [nm for _e, nm in op.keys])
        return ds

def group_apply(op, records):
    st = GroupState(op)
    for rec in records:
        st.add(rec)
    return st.snapshot()
