# Format string (strfmt-like)

KNOWN_TYPE_CHARS = set('beEfFfoxX%?')

class FormatSpec:
    __slots__ = ('fill','align','width','precision','typ')
    def __init__(self):
        self.fill=' '; self.align='<'; self.width=None; self.precision=None; self.typ=None

def parse_format_spec(spec):
    fs = FormatSpec()
    i = 0; n = len(spec)
    if n >= 2 and spec[1] in '<>^=':
        fs.fill = spec[0]
        fs.align = spec[1]
        i = 2
        if fs.align == '=':
            raise StartupError("Error: Invalid(sign aware zero padding and Align '=' not yet supported)")
    elif n >= 1 and spec[0] in '<>^=':
        fs.align = spec[0]
        i = 1
        if fs.align == '=':
            raise StartupError("Error: Invalid(sign aware zero padding and Align '=' not yet supported)")
    if i < n and spec[i] in '+- ':
        raise StartupError('Error: TypeError(Sign not allowed in string format specifier)')
    if i < n and spec[i] == '#':
        raise StartupError('Error: TypeError(Alternate form (#) not allowed in string format specifier)')
    if i < n and spec[i] == '0' and i + 1 < n and spec[i+1].isdigit():
        raise StartupError("Error: Invalid(sign aware zero padding and Align '=' not yet supported)")
    m = re.match(r'[0-9]+', spec[i:])
    if m:
        fs.width = int(m.group(0)); i += m.end()
    if i < n and spec[i] == '.':
        i += 1
        m = re.match(r'[0-9]+', spec[i:])
        if not m:
            raise StartupError('Error: Invalid(Format specifier missing precision)')
        fs.precision = int(m.group(0)); i += m.end()
    if i < n:
        ch = spec[i]
        if i != n - 1:
            raise StartupError('Error: Invalid(Invalid format specifier)')
        if ch == 's':
            fs.typ = 's'; i += 1
        elif ch in KNOWN_TYPE_CHARS:
            raise StartupError("Error: TypeError(Unknown format code Some('%s') for object of type 'str')" % ch)
        else:
            raise StartupError("Error: TypeError(Invalid type specifier: '%s')" % ch)
    if i != n:
        raise StartupError('Error: Invalid(Invalid format specifier)')
    return fs

def apply_format_spec(fs, s):
    if fs.precision is not None:
        s = ''.join(list(s)[:fs.precision])
    if fs.width is not None:
        chars = list(s)
        if len(chars) < fs.width:
            pad = fs.width - len(chars)
            if fs.align == '<':
                s = s + fs.fill * pad
            elif fs.align == '>':
                s = fs.fill * pad + s
            elif fs.align == '^':
                left = pad // 2
                right = pad - left
                s = fs.fill * left + s + fs.fill * right
    return s

class Formatter:
    def __init__(self, fmt):
        self.fmt = fmt
        self.parts = []
        i = 0; n = len(fmt); lit = []
        def flush():
            if lit:
                self.parts.append(('lit', ''.join(lit))); lit.clear()
        while i < n:
            ch = fmt[i]
            if ch == '{':
                if i + 1 < n and fmt[i+1] == '{':
                    lit.append('{'); i += 2; continue
                flush()
                j = i + 1
                inner = []
                while j < n and fmt[j] != '}':
                    if fmt[j] == '{':
                        raise StartupError('Error: Invalid(extra { found)')
                    inner.append(fmt[j]); j += 1
                if j >= n:
                    raise StartupError("Error: Invalid(Expected '}' before end of string)")
                inner_s = ''.join(inner)
                if ':' in inner_s:
                    name, spec = inner_s.split(':', 1)
                else:
                    name, spec = inner_s, ''
                if name == '':
                    raise StartupError('Error: Invalid(must specify identifier)')
                fs = parse_format_spec(spec) if spec != '' else FormatSpec()
                self.parts.append(('field', name, fs))
                i = j + 1; continue
            if ch == '}':
                if i + 1 < n and fmt[i+1] == '}':
                    lit.append('}'); i += 2; continue
                raise StartupError("Error: Invalid(Single '}' encountered in format string)")
            lit.append(ch); i += 1
        flush()
    def render(self, values):
        out = []
        for part in self.parts:
            if part[0] == 'lit':
                out.append(part[1])
            else:
                _t, name, fs = part
                v = values.get(name, None)
                out.append(apply_format_spec(fs, render_value(v)))
        return ''.join(out)

# ---------------------------------------------------------------------------
# Renderers

class WidthState:
    def __init__(self):
        self.widths = {}
    def update_inline(self, key, value_str):
        bl = len(value_str.encode('utf-8'))
        kl = len(key.encode('utf-8'))
        w = self.widths.get(key)
        if w is None:
            self.widths[key] = max(bl, kl)
        elif bl > w + 4:
            self.widths[key] = bl
    def update_table(self, name, cell_str):
        bl = len(cell_str.encode('utf-8'))
        kl = len(name.encode('utf-8'))
        w = self.widths.get(name)
        if w is None:
            self.widths[name] = max(bl, kl)
        elif bl > w + 4:
            self.widths[name] = bl

def _pad_chars(s, target):
    cl = len(s)
    if cl < target:
        return s + ' ' * (target - cl)
    return s

class Renderer:
    def __init__(self, mode, formatter=None, out=None):
        self.mode = mode
        self.formatter = formatter
        self.out = out
        self.inline_columns = []
        self.widths = WidthState()
        try:
            self.is_tty = bool(out.isatty())
        except Exception:
            self.is_tty = False
        self._live_lines = 0
    def write(self, text):
        b = (text + '\n').encode('utf-8', 'surrogatepass') if isinstance(text, str) else text
        try:
            self.out.write(b)
            self.out.flush()
        except (BrokenPipeError, OSError):
            raise BrokenPipeError()
    def render_inline(self, rec):
        if self.mode == 'json':
            obj = '{' + ','.join('%s:%s' % (json_escape_str(k), json_value_str(rec.data[k])) for k in sorted(rec.data.keys())) + '}'
            self.write(obj); return
        if self.mode == 'logfmt':
            self.write(' '.join('%s=%s' % (k, render_value(rec.data[k])) for k in sorted(rec.data.keys()))); return
        if self.mode == 'format':
            self.write(self.formatter.render(dict(rec.data))); return
        if not rec.data:
            self.write('' if self.inline_columns else rec.raw); return
        rendered = {}
        for k in sorted(rec.data.keys()):
            if k not in self.inline_columns:
                self.inline_columns.append(k)
            vs = render_value(rec.data[k])
            rendered[k] = vs
            self.widths.update_inline(k, vs)
        present = [k for k in self.inline_columns if k in rec.data]
        parts = []
        for pi, k in enumerate(present):
            cell = '[%s=%s]' % (k, rendered[k])
            if pi == len(present) - 1:
                parts.append(cell)
            else:
                target = len(k.encode('utf-8')) + self.widths.widths[k] + 3 + 8
                seg = _pad_chars(cell, target)
                idx_here = self.inline_columns.index(k)
                idx_next = self.inline_columns.index(present[pi+1])
                extra = ''
                for mk in self.inline_columns[idx_here+1:idx_next]:
                    extra += ' ' * (len(mk.encode('utf-8')) + self.widths.widths.get(mk, len(mk.encode('utf-8'))) + 3 + 8)
                parts.append(seg + extra)
        self.write(''.join(parts))
    def render_dataset(self, ds):
        if self.mode == 'json':
            objs = []
            for rec in ds.rows:
                inner = ','.join('%s:%s' % (json_escape_str(c), json_value_str(rec.data.get(c, None))) for c in ds.columns)
                objs.append('{' + inner + '}')
            self.write('[' + ','.join(objs) + ']')
            return
        if not ds.rows:
            if self.mode in ('legacy',):
                self.write('No data')
            return
        if self.mode == 'logfmt':
            for rec in ds.rows:
                d = {}
                for c in ds.columns:
                    d[c] = rec.data.get(c, None)
                self.write(' '.join('%s=%s' % (k, render_value(d[k])) for k in sorted(d.keys())))
            return
        if self.mode == 'format':
            for rec in ds.rows:
                d = {}
                for c in ds.columns:
                    d[c] = rec.data.get(c, None)
                self.write(self.formatter.render(d))
            return
        text = self.table_text(ds)
        for line in text:
            self.write(line)
    def draw_live(self, ds):
        import shutil
        lines = self.table_text(ds)
        try:
            height = shutil.get_terminal_size().lines
        except Exception:
            height = 24
