        lines = lines[:max_lines]
        buf = []
        if self._live_lines:
            if self._live_lines > 1:
                buf.append(chr(27) + '[%dA' % (self._live_lines - 1))
            buf.append('\r')
        total = max(len(lines), self._live_lines)
        for i in range(total):
