def _sort_one_cmp(a_err, a_val, b_err, b_val, desc):
    if a_err and b_err:
        return 0
    if a_err:
        return 1
    if b_err:
        return -1
    c = sort_cmp_value(a_val, b_val)
    return -c if desc else c

def sort_rows(rows, sort_keys, columns):
    """sort_keys: list of (expr, desc). Returns new list."""
    from functools import cmp_to_key
    keyed = []
    for rec in rows:
        ks = []
        for expr, desc in sort_keys:
            try:
                ks.append((False, eval_expr(expr, rec)))
            except EvalError:
                ks.append((True, None))
        keyed.append((rec, ks))
    def cmp(x, y):
        for (expr, desc), (ae, av), (be, bv) in zip(sort_keys, x[1], y[1]):
            c = _sort_one_cmp(ae, av, be, bv, desc)
            if c:
                return c
        for col in columns:
            av = x[0].data.get(col, None); bv = y[0].data.get(col, None)
            c = sort_cmp_value(av, bv)
            if c:
                return c
        return 0
    keyed.sort(key=cmp_to_key(cmp))
    return [r for r, _ in keyed]

def default_group_sort(ds):
    if not ds.group_sort:
        return
    from functools import cmp_to_key
    agg_names, key_names = ds.group_sort
    def cmp(x, y):
        for nm in agg_names:
            c = sort_cmp_value(x.data.get(nm, None), y.data.get(nm, None))
            if c:
                return -c
        for nm in key_names:
            c = sort_cmp_value(x.data.get(nm, None), y.data.get(nm, None))
            if c:
                return c
        for col in ds.columns:
            c = sort_cmp_value(x.data.get(col, None), y.data.get(col, None))
            if c:
                return c
        return 0
    ds.rows.sort(key=cmp_to_key(cmp))

