HELPER = '''
def _validate_unknown_functions(ops):
    def check(e):
        if e is None:
            return
        e = unwrap(e)
        if e.kind == 'call':
            name, args = e.args
            if name not in KNOWN_FUNCTIONS:
                raise StartupError('Error: Unknown function %s' % name)
            for a in args: check(a)
        elif e.kind in ('bin', 'cmp'):
            check(e.args[1]); check(e.args[2])
        elif e.kind in ('and', 'or'):
            check(e.args[0]); check(e.args[1])
        elif e.kind == 'not':
            check(e.args[0])
        elif e.kind == 'if':
            for a in e.args: check(a)
    for op in ops:
        for attr in ('expr', 'from_expr', 'arg_expr', 'as_expr'):
            if hasattr(op, attr):
                check(getattr(op, attr))
        if isinstance(op, GroupAggOp):
            for f in op.funcs: check(f.expr)
            for e, _n in op.keys: check(e)
        if isinstance(op, SortOp):
            for e, _d in op.keys: check(e)
'''
